	path := filepath.Join(repoDir, ".brainignore")
	info, err := os.Stat(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("stat .brainignore: %w", err)
	}
	if info.IsDir() {
		return nil, errors.New(".brainignore is a directory")
	}
	return []string{path}, nil
}

