  3285	func parseBrainLiveStatus(status []byte) (staged, unstaged, untracked []string) {
  3286		for _, line := range strings.Split(string(status), "\n") {
  3287			if strings.TrimSpace(line) == "" {
  3288				continue
  3289			}
  3290			paths := worktreeStatusPaths(line)
  3291			if len(paths) == 0 {
  3292				continue
  3293			}
  3294			if strings.HasPrefix(line, "?? ") {
  3295				untracked = append(untracked, paths...)
  3296				continue
  3297			}
  3298			index := byte(' ')
  3299			worktree := byte(' ')
  3300			if len(line) > 0 {
  3301				index = line[0]
  3302			}
  3303			if len(line) > 1 {
  3304				worktree = line[1]
  3305			}
  3306			if index != ' ' && index != '?' {
  3307				staged = append(staged, paths...)
  3308			}
  3309			if worktree != ' ' && worktree != '?' {
  3310				unstaged = append(unstaged, paths...)
  3311			}
  3312		}
  3313		sort.Strings(staged)
  3314		sort.Strings(unstaged)
  3315		sort.Strings(untracked)
  3316		return staged, unstaged, untracked
  3317	}
