   238	func retrievalSiblingImplementationCandidates(testFile string) []string {
   239		ext := filepath.Ext(testFile)
   240		switch {
   241		case strings.HasSuffix(testFile, "_test.go"):
   242			return []string{strings.TrimSuffix(testFile, "_test.go") + ".go"}
   243		case strings.HasSuffix(testFile, "_test.py"):
   244			return []string{strings.TrimSuffix(testFile, "_test.py") + ".py"}
   245		case strings.Contains(testFile, ".test"+ext):
   246			return []string{strings.Replace(testFile, ".test"+ext, ext, 1)}
   247		case strings.Contains(testFile, ".spec"+ext):
   248			return []string{strings.Replace(testFile, ".spec"+ext, ext, 1)}
   249		default:
   250			return nil
   251		}
   252	}
