   254	func compactUnifiedResults(results []unifiedResult, query string) []compactUnifiedResult {
   255		if results == nil {
   256			return []compactUnifiedResult{}
   257		}
   258		out := make([]compactUnifiedResult, len(results))
   259		for i, result := range results {
   260			out[i] = compactUnifiedResult{
   261				Source: result.Source, ID: result.ID, Path: result.Path, Heading: result.Heading, Line: result.Line,
   262				Text: result.Text, Excerpt: retrievalResultExcerpt(result.Text, query, retrievalExcerptBytes), Score: result.Score,
   263				VerificationRequired: result.VerificationRequired, Caveats: result.Caveats, RelatedIDs: result.RelatedIDs,
   264			}
   265		}
   266		return out
   267	}
