   120	func mcpDebugToolCall(raw json.RawMessage) mcpDebugToolCallInfo {
   121		var params struct {
   122			Name      string         `json:"name"`
   123			Arguments map[string]any `json:"arguments"`
   124		}
   125		if err := json.Unmarshal(raw, &params); err != nil {
   126			return mcpDebugToolCallInfo{}
   127		}
   128		name := strings.TrimSpace(params.Name)
   129		if name == "" {
   130			return mcpDebugToolCallInfo{}
   131		}
   132		name = strings.Map(func(r rune) rune {
   133			if r < 32 || r == 127 {
   134				return -1
   135			}
   136			return r
   137		}, name)
   138		safe := make(map[string]any)
   139		for _, key := range []string{"blind_spots", "include_deletions", "location_only"} {
   140			if value, ok := params.Arguments[key].(bool); ok {
   141				safe[key] = value
   142			}
   143		}
   144		if name == "brain_workspace_graph" || name == "brain_workspace_regressions" || name == "brain_workspace_review" {
   145			if value, ok := params.Arguments["workspace"].(string); ok {
   146				workspace := strings.TrimSpace(value)
   147				if validateWorkspaceName(workspace) == nil {
   148					safe["workspace"] = workspace
   149				}
   150			}
   151		}
   152		return mcpDebugToolCallInfo{name: name, safeArgs: safe}
   153	}
