451	// recentDecisionMatches returns the most recent decision records so an agent can
452	// see how the project's design has been steered, newest first.
453	func recentDecisionMatches(brainDir string, source *historySourceManifest, limit int) []brainTextMatch {
454		if limit <= 0 {
455			return nil
456		}
457		index, err := loadBrainHistoryIndex(brainDir, source)
458		if err != nil {
459			return nil
460		}
461		var decisions []historyRecord
462		for _, record := range index.Records {
463			if record.Kind == "decision" {
464				decisions = append(decisions, record)
465			}
466		}
467		sort.SliceStable(decisions, func(i, j int) bool {
468			left, leftOK := historyRecordTimestamp(decisions[i].Path)
469			right, rightOK := historyRecordTimestamp(decisions[j].Path)
470			if leftOK && rightOK && !left.Equal(right) {
471				return left.After(right)
472			}
473			return leftOK && !rightOK
474		})
475		seen := map[string]struct{}{}
476		var matches []brainTextMatch
477		for _, record := range decisions {
478			key := normalizeHistorySearchText(record.Summary)
479			if _, ok := seen[key]; ok {
480				continue
481			}
482			seen[key] = struct{}{}
483			match := historyRecordTextMatch(record)
484			match.Excerpt = strings.TrimSpace(truncateString(match.Excerpt, 280))
485			matches = append(matches, match)
486			if len(matches) >= limit {
487				break
488			}
489		}
490		return matches
491	}
