558	// freshnessSummary collapses the freshness axes into a single human line: "ok"
559	// when everything is current, otherwise the non-ok axes and their details. This
560	// is the compact freshness view callers can show instead of the full axis map.
561	func freshnessSummary(report staleReport) string {
562		if report.Severity == "ok" {
563			return "all axes current"
564		}
565		keys := make([]string, 0, len(report.Axes))
566		for key := range report.Axes {
567			keys = append(keys, key)
568		}
569		sort.Strings(keys)
570		var parts []string
571		for _, key := range keys {
572			axis := report.Axes[key]
573			if axis.State == "ok" || axis.State == "clean" {
574				continue
575			}
576			if axis.Detail != "" {
577				parts = append(parts, fmt.Sprintf("%s=%s (%s)", key, axis.State, axis.Detail))
578			} else {
579				parts = append(parts, fmt.Sprintf("%s=%s", key, axis.State))
580			}
581		}
582		return strings.Join(parts, "; ")
583	}
