   139	// rankDocsViaFTS ranks doc chunks by BM25, trimming the weak tail at 30% of the
   140	// top score (like history). ok=false on any failure or a degenerate query.
   141	// rankDocsLexical is the in-memory fallback for when the doc FTS index can't be
   142	// built or opened: it scores each doc by how many distinct query terms appear in
   143	// its indexed content, so the `doc` source still contributes to search/query when
   144	// SQLite/FTS is unavailable — mirroring history's substring fallback. Best-effort:
   145	// the only floor is "shares at least one query term".
   146	func rankDocsLexical(index docIndex, query string, limit int) []scoredDocRecord {
   147		terms := historyQueryAllTerms(query)
   148		if len(terms) == 0 || limit <= 0 {
   149			return nil
   150		}
   151		type sc struct {
   152			rec   docRecord
   153			score int
   154		}
   155		scored := make([]sc, 0, len(index.Records))
   156		for _, r := range index.Records {
   157			content := docFTSContent(r)
   158			n := 0
   159			for _, t := range terms {
   160				if t != "" && strings.Contains(content, strings.ToLower(t)) {
   161					n++
   162				}
   163			}
   164			if n > 0 {
   165				scored = append(scored, sc{r, n})
   166			}
   167		}
   168		sort.SliceStable(scored, func(a, b int) bool {
   169			left := docTrustAdjustedScore(float64(scored[a].score), scored[a].rec.Historical)
   170			right := docTrustAdjustedScore(float64(scored[b].score), scored[b].rec.Historical)
   171			if left != right {
   172				return left > right
   173			}
   174			return scored[a].rec.ID < scored[b].rec.ID
   175		})
   176		out := make([]scoredDocRecord, 0, min(limit, len(scored)))
