   116	func resolveXDGDir(pluginDir, pluginEnv, xdgEnv, homeFallback string) (string, error) {
   117		if pluginDir != "" {
   118			if !filepath.IsAbs(pluginDir) {
   119				return "", fmt.Errorf("%s must be absolute, got %q", pluginEnv, pluginDir)
   120			}
   121			return pluginDir, nil
   122		}
   123		if xdg := os.Getenv(xdgEnv); xdg != "" {
   124			if filepath.IsAbs(xdg) {
   125				return filepath.Join(xdg, xdgRootDir), nil
   126			}
   127			// XDG says relative paths are invalid; ignore and fall back to HOME.
   128		}
   129		home, err := os.UserHomeDir()
   130		if err != nil {
   131			return "", fmt.Errorf("resolve home dir: %w", err)
   132		}
   133		return filepath.Join(home, homeFallback), nil
   134	}
