func TestSQLiteReadOnlyDSNObservesRuntimeTraceWrites(t *testing.T) {
	storePath := filepath.Join(t.TempDir(), semanticSQLiteName)
	writer, err := sql.Open(sqliteDriverName, storePath)
	if err != nil {
		t.Fatal(err)
	}
	defer writer.Close()
	if err := initializeSemanticSQLite(writer); err != nil {
		t.Fatal(err)
	}

