  1137	// semanticEndpointPath extracts the repository-relative file path encoded in a
  1138	// semantic relation endpoint ID, or "" when the ID carries no path. Internal
  1139	// IDs are "<repo-key>:<lang>:<path>:<kind>:<name>"; the repo key, language, and
  1140	// kind segments never contain ":", so the path is always the third field.
  1141	// External endpoints ("external:<kind>:<value>") carry no file path. Endpoint
  1142	// IDs are filtered against the ignore set by file path so a substring in the
  1143	// repo key or symbol name cannot accidentally redact unrelated relations.
  1144	func semanticEndpointPath(id string) string {
  1145		if id == "" || strings.HasPrefix(id, "external:") {
  1146			return ""
  1147		}
  1148		parts := strings.Split(id, ":")
  1149		if len(parts) < 5 {
  1150			return ""
  1151		}
  1152		return parts[2]
  1153	}
