144	// resolveFactsBackendName folds the --facts-backend flag, the env override, and
145	// the default into a single backend name.
146	func resolveFactsBackendName(flagVal string) string {
147		if v := strings.TrimSpace(flagVal); v != "" {
148			return v
149		}
150		if v := strings.TrimSpace(os.Getenv(envFactsBackend)); v != "" {
151			return v
152		}
153		return factsBackendLocalGitmeta
154	}
155	
156	// buildFactsSyncBackend constructs the selected Server, returning it, the repoID
157	// to thread through Sync, and a human label for output. The local-gitmeta path
158	// is keyed by the repo storage key; the http path mirrors publish's opt-in gates
159	// and flag/env resolution.
160	func buildFactsSyncBackend(opts Options, backend string, storage repoStorage, syncOpts factsSyncOptions) (factsync.Server, string, string, error) {
161		switch backend {
162		case factsBackendLocalGitmeta:
163			gitDir, err := gitmetaDirForKey(opts.Env, storage.Key)
164			if err != nil {
165				return nil, "", "", err
166			}
167			b, err := factgitmeta.NewLocalBackend(gitDir, storage.Key, opts.Now)
168			if err != nil {
169				return nil, "", "", err
170			}
171			return b, storage.Key, "local-gitmeta (" + gitDir + ")", nil
172	
173		case factsBackendHTTP:
174			// The master local-only switch always wins over the hosted opt-in.
175			if brainNoEgressMode() {
176				return nil, "", "", fmt.Errorf("no_egress: hosted fact sync is disabled while ENTIRE_BRAIN_NO_EGRESS or ENTIRE_BRAIN_LOCAL_ONLY is set; unset it or use --facts-backend=local-gitmeta")
177			}
178			// Hosted egress is opt-in and fails closed (mirrors publish).
179			if !envBool(envBrainAllowHosted) {
180				return nil, "", "", fmt.Errorf("hosted_sync_disabled: the http fact backend is opt-in and off by default; set %s=1 to enable it, or use --facts-backend=local-gitmeta", envBrainAllowHosted)
181			}
182			repoID := publishFlagOrEnv(syncOpts.repoID, envRepoID)
183			if repoID == "" {
184				return nil, "", "", fmt.Errorf("facts sync: target repo id is required for the http backend; set --repo-id or %s", envRepoID)
185			}
186			baseURL := publishFlagOrEnv(syncOpts.apiURL, envAPIBaseURL)
187			if baseURL == "" {
188				return nil, "", "", fmt.Errorf("facts sync: API base URL is required for the http backend; set --api-url or %s", envAPIBaseURL)
189			}
190			token := publishFlagOrEnv(syncOpts.token, envAPIToken)
191			if token == "" {
192				return nil, "", "", fmt.Errorf("facts sync: API token is required for the http backend; set --token or %s", envAPIToken)
193			}
194			return &factsync.HTTPServer{BaseURL: baseURL, Token: token}, repoID, "http (" + strings.TrimRight(baseURL, "/") + ")", nil
195	
196		default:
197			return nil, "", "", fmt.Errorf("unknown --facts-backend %q (want %q or %q)", backend, factsBackendLocalGitmeta, factsBackendHTTP)
198		}
199	}
