    71	// TestBackendRoundTripPersistsToDisk proves the create→read round-trip returns
    72	// the EXACT bytes and content ref, writes a real bare git repo, and survives a
    73	// reopen (durability across process restarts).
    74	func TestBackendRoundTripPersistsToDisk(t *testing.T) {
    75		ctx := context.Background()
    76		b, dir := newBackend(t)
    77	
    78		// No head yet → Current reports not-found with a nil blob (merge into empty).
    79		if ref, blob, found, err := b.Current(ctx, "repo", "main"); err != nil || found || ref != "" || blob != nil {
    80			t.Fatalf("Current on empty = (%q,%v,%v,%v); want (\"\",nil,false,nil)", ref, blob, found, err)
    81		}
    82	
    83		plaintext := ndjson(t, fact("the build uses bazel", []string{"build/tooling"}, "s1"))
    84		ref, err := b.Advance(ctx, "repo", "main", "", plaintext)
    85		if err != nil {
    86			t.Fatalf("Advance create: %v", err)
    87		}
    88		if want := FactSetRef(plaintext); ref != want {
    89			t.Fatalf("Advance ref = %q; want content ref %q", ref, want)
    90		}
    91	
    92		gotRef, gotBlob, found, err := b.Current(ctx, "repo", "main")
    93		if err != nil || !found {
    94			t.Fatalf("Current after advance: found=%v err=%v", found, err)
    95		}
    96		if gotRef != ref {
    97			t.Fatalf("Current ref = %q; want %q", gotRef, ref)
    98		}
    99		if !bytes.Equal(gotBlob, plaintext) {
   100			t.Fatalf("Current blob = %q; want %q (byte-for-byte)", gotBlob, plaintext)
   101		}
   102	
   103		// It really wrote a git repo — not an in-memory store.
   104		for _, rel := range []string{"HEAD", filepath.Join("refs", "meta", "local", "main")} {
   105			if _, statErr := os.Stat(filepath.Join(dir, rel)); statErr != nil {
