   121	// TestBackendAdvanceNoChange proves re-advancing the identical content from the
   122	// current ref is a no-op (ErrNoChange) and does not move the head.
   123	func TestBackendAdvanceNoChange(t *testing.T) {
   124		ctx := context.Background()
   125		b, _ := newBackend(t)
   126	
   127		plaintext := ndjson(t, fact("a", []string{"x"}, "s1"))
   128		ref, err := b.Advance(ctx, "repo", "main", "", plaintext)
   129		if err != nil {
   130			t.Fatalf("advance: %v", err)
   131		}
   132	
   133		if _, err := b.Advance(ctx, "repo", "main", ref, plaintext); !errors.Is(err, factsync.ErrNoChange) {
   134			t.Fatalf("Advance identical content = %v; want ErrNoChange", err)
   135		}
   136		// Head unchanged.
   137		if gotRef, _, _, _ := b.Current(ctx, "repo", "main"); gotRef != ref {
   138			t.Fatalf("head moved on no-change: %q != %q", gotRef, ref)
   139		}
   140	}
