   142	// TestBackendAdvanceConflict proves both conflict shapes map to ErrConflict — a
   143	// stale/unknown oldRef and a create over an existing head — leave the head
   144	// untouched (no partial write), and that advancing from the correct ref then
   145	// succeeds.
   146	func TestBackendAdvanceConflict(t *testing.T) {
   147		ctx := context.Background()
   148		b, _ := newBackend(t)
   149	
   150		v1 := ndjson(t, fact("a", []string{"x"}, "s1"))
   151		ref1, err := b.Advance(ctx, "repo", "main", "", v1)
   152		if err != nil {
   153			t.Fatalf("advance v1: %v", err)
   154		}
   155	
   156		v2 := ndjson(t, fact("a", []string{"x"}, "s1"), fact("b", []string{"y"}, "s2"))
   157	
   158		// Stale oldRef → conflict.
   159		if _, err := b.Advance(ctx, "repo", "main", "facts-stale", v2); !errors.Is(err, factsync.ErrConflict) {
   160			t.Fatalf("Advance stale oldRef = %v; want ErrConflict", err)
   161		}
   162		// Create (oldRef="") over an existing head → conflict.
   163		if _, err := b.Advance(ctx, "repo", "main", "", v2); !errors.Is(err, factsync.ErrConflict) {
   164			t.Fatalf("Advance create-over-existing = %v; want ErrConflict", err)
   165		}
   166		// Mutation-verified: the head is UNCHANGED after the failed advances.
   167		if gotRef, gotBlob, _, _ := b.Current(ctx, "repo", "main"); gotRef != ref1 || !bytes.Equal(gotBlob, v1) {
   168			t.Fatalf("head changed after conflict: ref=%q", gotRef)
   169		}
   170	
   171		// Advancing from the CORRECT current ref succeeds and moves the head.
   172		ref2, err := b.Advance(ctx, "repo", "main", ref1, v2)
   173		if err != nil {
   174			t.Fatalf("advance v2 from correct ref: %v", err)
   175		}
   176		if ref2 == ref1 {
   177			t.Fatalf("ref did not advance: still %q", ref1)
   178		}
   179		_, gotBlob, _, _ := b.Current(ctx, "repo", "main")
   180		if got := factTexts(t, gotBlob); !got["a"] || !got["b"] {
   181			t.Fatalf("post-advance head missing facts: %v", got)
   182		}
   183	}
