   185	// interposeOnce wraps a Server and, once armed, runs a competing member's full
   186	// Sync immediately after the next Current — staling the caller's read so its
   187	// following Advance loses the value-CAS and must re-read + re-merge. It mirrors
   188	// factsync/sync_test's conflictOnceServer, but drives the REAL local backend.
   189	type interposeOnce struct {
   190		inner      factsync.Server
   191		competitor []factmerge.Record
   192		now        time.Time
   193		armed      bool
   194	}
   195	
   196	func (s *interposeOnce) Current(ctx context.Context, repoID, branch string) (string, []byte, bool, error) {
   197		ref, blob, found, err := s.inner.Current(ctx, repoID, branch)
   198		if s.armed {
   199			s.armed = false
   200			if _, aerr := factsync.Sync(ctx, s.inner, repoID, branch, "member-C", s.competitor, s.now); aerr != nil {
   201				return "", nil, false, aerr
   202			}
   203		}
   204		return ref, blob, found, err
   205	}
   206	
   207	func (s *interposeOnce) Advance(ctx context.Context, repoID, branch, oldRef string, plaintext []byte) (string, error) {
   208		return s.inner.Advance(ctx, repoID, branch, oldRef, plaintext)
   209	}
