   320	// TestBackendBlobDoesNotAccumulate is the regression for unbounded blob growth:
   321	// the live git-meta state must hold exactly ONE blob record (the current
   322	// fact-set), not one per historical version, or Materialize/Serialize grow
   323	// O(versions) on every sync. Prior versions live in git history, not the tree.
   324	func TestBackendBlobDoesNotAccumulate(t *testing.T) {
   325		b, _ := newBackend(t)
   326		ctx := context.Background()
   327		oldRef := ""
   328		for i := 0; i < 4; i++ {
   329			blob := ndjson(t, fact("fact "+strconv.Itoa(i), []string{"topic/x"}, "s"+strconv.Itoa(i)))
   330			ref, err := b.Advance(ctx, "repo", "main", oldRef, blob)
   331			if err != nil {
   332				t.Fatalf("advance %d: %v", i, err)
   333			}
   334			oldRef = ref
   335		}
   336		st, _, err := b.state()
   337		if err != nil {
   338			t.Fatalf("state: %v", err)
   339		}
   340		blobs := 0
   341		for _, s := range st.Strings {
   342			if strings.HasSuffix(s.Key, ":blob") {
   343				blobs++
   344			}
   345		}
   346		if blobs != 1 {
   347			t.Fatalf("want exactly 1 live blob record after 4 advances, got %d", blobs)
   348		}
