func runFactsSync(cmd *cobra.Command, opts Options, syncOpts factsSyncOptions) error {
	ctx := cmd.Context()

	repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
	if err != nil {
		return err
	}
	if !local {
		return fmt.Errorf("facts sync requires a local repository path")
	}
	storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
	if err != nil {
		return err
	}

	branch := strings.TrimSpace(syncOpts.branch)
	if branch == "" {
		if current, gitErr := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
			branch = strings.TrimSpace(current)
		}
	}
	if branch == "" {
		branch = distillDefaultBranch
	}

	facts, err := loadFacts(storage.BrainDir, branch)
	if err != nil {
		return err
	}
	memberID := resolveSyncMemberID(ctx, opts.Runner, repoDir, syncOpts.member)

	srv, repoID, backendLabel, err := buildFactsSyncBackend(opts, resolveFactsBackendName(syncOpts.backend), storage, syncOpts)
	if err != nil {
		return err
	}

	// The merge runs on this runner (ADR-P1-E); the backend only stores the blob
	// and CAS-swaps the head. Sync retries on a losing swap and never drops a
	// member's fact.
	res, err := factsync.Sync(ctx, srv, repoID, branch, memberID, facts, opts.Now().UTC())
	if err != nil {
		return err
	}

	if syncOpts.jsonOut {
		return writeJSON(cmd, map[string]any{
			"branch":    branch,
			"backend":   backendLabel,
			"member":    memberID,
			"published": res.Published,
			"ref":       res.NewRef,
			"attempts":  res.Attempts,
			"proposals": res.Proposals,
			"facts":     len(facts),
		})
	}

	out := cmd.OutOrStdout()
	if res.Published {
		fmt.Fprintf(out, "synced %d local fact(s) on %s via %s: head advanced to %s (%d attempt(s))\n",
			len(facts), branch, backendLabel, res.NewRef, res.Attempts)
	} else {
		fmt.Fprintf(out, "synced %d local fact(s) on %s via %s: no change; head at %s (%d attempt(s))\n",
			len(facts), branch, backendLabel, refOrNone(res.NewRef), res.Attempts)
	}
	if len(res.Proposals) > 0 {
		fmt.Fprintf(out, "%d cross-member conflict(s) queued for review:\n", len(res.Proposals))
		for _, p := range res.Proposals {
			fmt.Fprintf(out, "  %s %s -> %s (by %s, confidence %.2f)\n", p.Action, p.CandidateID, p.TargetID, p.ProposedBy, p.Confidence)
		}
	}
	return nil
}

// resolveFactsBackendName folds the --facts-backend flag, the env override, and
// the default into a single backend name.
func resolveFactsBackendName(flagVal string) string {
	if v := strings.TrimSpace(flagVal); v != "" {
		return v
	}
	if v := strings.TrimSpace(os.Getenv(envFactsBackend)); v != "" {
		return v
	}
	return factsBackendLocalGitmeta
}

// buildFactsSyncBackend constructs the selected Server, returning it, the repoID
// to thread through Sync, and a human label for output. The local-gitmeta path
// is keyed by the repo storage key; the http path mirrors publish's opt-in gates
// and flag/env resolution.
func buildFactsSyncBackend(opts Options, backend string, storage repoStorage, syncOpts factsSyncOptions) (factsync.Server, string, string, error) {
	switch backend {
	case factsBackendLocalGitmeta:
		gitDir, err := gitmetaDirForKey(opts.Env, storage.Key)
		if err != nil {
			return nil, "", "", err
		}
		b, err := factgitmeta.NewLocalBackend(gitDir, storage.Key, opts.Now)
		if err != nil {
			return nil, "", "", err
		}
		return b, storage.Key, "local-gitmeta (" + gitDir + ")", nil

	case factsBackendHTTP:
		// The master local-only switch always wins over the hosted opt-in.
		if brainNoEgressMode() {
			return nil, "", "", fmt.Errorf("no_egress: hosted fact sync is disabled while ENTIRE_BRAIN_NO_EGRESS or ENTIRE_BRAIN_LOCAL_ONLY is set; unset it or use --facts-backend=local-gitmeta")
		}
		// Hosted egress is opt-in and fails closed (mirrors publish).
		if !envBool(envBrainAllowHosted) {
			return nil, "", "", fmt.Errorf("hosted_sync_disabled: the http fact backend is opt-in and off by default; set %s=1 to enable it, or use --facts-backend=local-gitmeta", envBrainAllowHosted)
package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

const factsProposalsFileName = "proposals.ndjson"

func factsProposalsRelPath(branch string) string {
	return filepath.ToSlash(filepath.Join(factsBranchRelDir(branch), factsProposalsFileName))
}

// loadFactProposals reads a branch's pending proposals; a missing file yields
// none. A malformed line is a hard error so a corrupt queue is surfaced.
func loadFactProposals(brainDir, branch string) ([]factProposal, error) {
	path := filepath.Join(brainDir, filepath.FromSlash(factsProposalsRelPath(branch)))
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var proposals []factProposal
	for i, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		var p factProposal
		if err := json.Unmarshal([]byte(line), &p); err != nil {
			return nil, fmt.Errorf("parse %s line %d: %w", factsProposalsRelPath(branch), i+1, err)
		}
		proposals = append(proposals, p)
	}
	return proposals, nil
}

// writeFactProposals persists a branch's pending proposals, deduplicated by
// (action, candidate, target) and sorted for a stable file. An empty set
// removes the file so a fully-resolved branch leaves no stale queue.
func writeFactProposals(brainDir, branch string, proposals []factProposal) error {
	deduped := dedupeProposals(proposals)
	if len(deduped) == 0 {
		return removeBrainRelativeFile(brainDir, factsProposalsRelPath(branch))
	}
	var buf strings.Builder
	for _, p := range deduped {
		data, err := json.Marshal(p)
		if err != nil {
			return err
		}
		buf.Write(data)
		buf.WriteByte('\n')
	}
	return writeBrainRelativeFileAtomic(brainDir, factsProposalsRelPath(branch), []byte(buf.String()), 0o600)
}

func dedupeProposals(proposals []factProposal) []factProposal {
	seen := make(map[string]struct{}, len(proposals))
	out := make([]factProposal, 0, len(proposals))
	for _, p := range proposals {
		key := p.Action + "\x00" + p.CandidateID + "\x00" + p.TargetID
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, p)
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].TargetID != out[j].TargetID {
			return out[i].TargetID < out[j].TargetID
		}
		return out[i].CandidateID < out[j].CandidateID
	})
	return out
}

const (
	// maxReconcileExisting bounds how many existing active facts at a
	// candidate's paths are shown to the agent, keeping the reconcile prompt
	// bounded even on busy paths. When more exist, the most recently updated
	// are shown and the cap is reported as a warning (no silent truncation).
	maxReconcileExisting = 50
)

// reconcilePrompt is the static system prompt for the reconcile pass. The
// dynamic candidate/existing lists are supplied on stdin (see reconcileInput).
// Like the distill prompt it must not begin with a dash — the agent runners
// pass it as a positional CLI argument.
func reconcilePrompt() string {
	return `You are deduplicating durable repository facts. On stdin you receive two
numbered lists: CANDIDATES (new facts just extracted from a session) and
EXISTING (facts already stored at the same taxonomy paths). For each candidate,
decide how it relates to the existing facts.

For every candidate output exactly one line, in candidate-number order:

    <candidate#> <decision> <existing#-or-dash> <confidence>

- <candidate#>: the candidate's number.
- <decision>: one of
    new        — not represented by any existing fact.
    merge       — the SAME meaning as an existing fact (a restatement); consolidate.
    supersede   — CONTRADICTS or replaces an existing fact (the candidate is newer/correct).
- <existing#-or-dash>: for merge/supersede, the EXISTING fact number it refers
  to; for new, a dash "-".
- <confidence>: 0.00 to 1.00, your confidence in a merge/supersede decision
  (use 1.0 for new).

Rules:
- A restatement ("use tabs") and a reversal ("use spaces") look similar but are
  NOT the same: the first is merge, the second is supersede. Read the meaning.
- When unsure between merge/supersede and new, prefer new with lower confidence
  rather than wrongly collapsing distinct facts.
- Output only these lines. No prose, no headers, no blank lines.

Example:
1 new - 1.0
2 merge 3 0.88
3 supersede 1 0.93`

