	if !ok || stem == "" || strings.HasPrefix(stem, "_") || strings.Contains(stem, ".") || strings.HasSuffix(stem, "_test") {
		return "", false
	}
	return strings.TrimSuffix(clean, "_test.go") + ".go", true
}

