1517	func brainBriefLikelyFileGroups(repoRoot string, report brainBriefReport, task string) ([]string, []string, []string) {
1518		counts := map[string]int{}
1519		var currentFileCache map[string]bool
1520		taskTerms := brainBriefFileMatchTerms(task)
1521		add := func(path string, weight int, requireCurrentFile bool) {
1522			clean, ok := cleanBrainBriefLikelyFile(path)
1523			if !ok {
1524				return
1525			}
1526			// Semantic results come from an indexed snapshot, so a syntactically
1527			// valid path may have departed from the current worktree. Live changed
1528			// paths and history are intentionally exempt: a deleted live file can be
1529			// a restoration target, and history may name a file the task must create.
1530			if requireCurrentFile && repoRoot != "" {
1531				if currentFileCache == nil {
1532					currentFileCache = make(map[string]bool)
1533				}
1534				exists, cached := currentFileCache[clean]
1535				if !cached {
1536					exists = brainBriefRepoFileExists(repoRoot, clean)
1537					currentFileCache[clean] = exists
1538				}
1539				if !exists {
1540					return
1541				}
1542			}
1543			counts[clean] += weight + brainBriefLikelyFileBonus(clean) + brainBriefTaskTermBonus(clean, taskTerms)
1544		}
1545		for _, symbol := range report.Semantic.Context.Symbols {
1545		for _, symbol := range report.Semantic.Context.Symbols {
1546			add(symbol.FilePath, 12, true)
1547			add(symbol.Path, 4, true)
1548		}
1549		for _, relation := range report.Semantic.Context.Relations {
1550			add(relation.FilePath, 4, true)
1551			add(relation.Path, 2, true)
1552		}
1553		for _, trace := range report.Semantic.RuntimeTraces {
1554			add(trace.FilePath, 7, true)
1555			add(trace.Path, 3, true)
1556			for _, evidence := range trace.Evidence {
1557				add(evidence.FilePath, 2, true)
1558			}
1559		}
1560		for _, root := range report.Semantic.Tests.Roots {
1561			add(root.FilePath, 6, true)
1562		}
1563		for _, suggestion := range semanticTestSuggestionsForSynthesis(report.Semantic.Tests) {
1564			add(suggestion.Symbol.FilePath, 9, true)
1565		}
1566		for _, changed := range report.Status.Live.ChangedFiles {
1567			add(changed, 3, false)
1568		}
1569		for _, match := range report.History.Matches {
1570			for _, path := range extractBrainBriefPaths(match.Excerpt) {
1571				add(path, 5, false)
1572			}
1573		}
1574		for path, score := range brainBriefCurrentCodeFileCounts(repoRoot, task) {
1575			add(path, score, false)
1576		}
1577		editCounts := map[string]int{}
1578		testCounts := map[string]int{}
1579		for path, score := range counts {
1580			if brainBriefLikelyTestFile(path) {
1581				testCounts[path] = score
1582			} else {
1583				editCounts[path] = score
1584			}
1585		}
1586		editFiles := rankedBrainBriefLikelyFiles(editCounts, 8)
1587		testFiles := rankedBrainBriefLikelyFiles(testCounts, 6)
1588		all := append([]string{}, editFiles...)
1589		for _, file := range testFiles {
1590			if len(all) >= 12 {
1591				break
1592			}
1593			all = append(all, file)
1594		}
1595		return editFiles, testFiles, all
1596	}
