1598	func brainBriefCurrentCodeFileCounts(repoRoot, task string) map[string]int {
1599		if brainBriefPreviousResponseTask(task) {
1600			return brainBriefCurrentCodeFileCountsByScore(repoRoot, brainBriefPreviousResponseFileScore)
1601		}
1602		if !brainBriefProviderMetadataTask(task) {
1603			return nil
1604		}
1605		return brainBriefCurrentCodeFileCountsByScore(repoRoot, brainBriefProviderMetadataFileScore)
