1608	func brainBriefCurrentCodeFileCountsByScore(repoRoot string, scoreFile func(string, string) int) map[string]int {
1609		counts := map[string]int{}
1610		walked := 0
1611		_ = filepath.WalkDir(repoRoot, func(path string, d fs.DirEntry, err error) error {
1612			if err != nil {
1613				return nil
1614			}
1615			if path == repoRoot {
1616				return nil
1617			}
1618			rel, relErr := filepath.Rel(repoRoot, path)
1619			if relErr != nil {
1620				return nil
1621			}
1622			rel = filepath.ToSlash(rel)
1623			if d.IsDir() {
1624				if brainBriefSkipSourceDir(rel) {
1625					return filepath.SkipDir
1626				}
1627				return nil
1628			}
1629			if walked >= 2500 || !brainBriefSourceFile(rel) {
1630				return nil
1631			}
1632			walked++
1633			info, statErr := d.Info()
1634			if statErr != nil || info.Size() > brainInspectHistoryMaxBytes {
1635				return nil
1636			}
1637			data, readErr := brainBriefReadRepoFile(repoRoot, rel)
1638			if readErr != nil {
1639				return nil
1640			}
1641			score := scoreFile(rel, string(data))
1642			if score >= 90 {
1643				counts[rel] = score
1644			}
1645			return nil
1646		})
1647		return counts
1648	}
