1650	func brainBriefReadRepoFile(repoRoot, rel string) ([]byte, error) {
1651		clean, ok := cleanBrainBriefRepoRelativePath(rel)
1652		if !ok {
1653			return nil, fmt.Errorf("repo-relative path is unsafe: %s", rel)
1654		}
1655		nativeRel := filepath.FromSlash(clean)
1656		if err := rejectSymlinkPathComponents(repoRoot, nativeRel); err != nil {
1657			return nil, err
1658		}
1659		return os.ReadFile(filepath.Join(repoRoot, nativeRel))
