func brainBriefJSONProjection(report brainBriefReport) brainBriefJSONReport {
	out := brainBriefJSONReport{
		GeneratedAt:        report.GeneratedAt,
		Task:               report.Task,
		Status:             report.Status,
		History:            report.History,
		FactsLocusDrift:    report.FactsLocusDrift,
		FactsPendingReview: report.FactsPendingReview,
		ActionChecklist:    report.ActionChecklist,
		LikelyEditFiles:    report.LikelyEditFiles,
		LikelyTestFiles:    report.LikelyTestFiles,
		LikelyFiles:        report.LikelyFiles,
		Guidance:           report.Guidance,
		Warnings:           report.Warnings,
	}
	out.Semantic.Context.Symbols = compactSemanticRecords(report.Semantic.Context.Symbols)
	out.Semantic.Context.Relations = compactSemanticRecords(report.Semantic.Context.Relations)
	out.Semantic.Context.Neighbors = compactSemanticRecords(report.Semantic.Context.Neighbors)
	out.Semantic.RuntimeTraces = compactSemanticRecords(report.Semantic.RuntimeTraces)
	out.Semantic.Tests.Roots = compactSemanticRecords(report.Semantic.Tests.Roots)
	out.Semantic.Tests.Suggestions = make([]compactSemanticTestSuggestion, len(report.Semantic.Tests.Suggestions))
	for i, suggestion := range report.Semantic.Tests.Suggestions {
		out.Semantic.Tests.Suggestions[i] = compactSemanticTestSuggestion{
			Symbol: compactSemanticRecordFrom(suggestion.Symbol),
			Reason: suggestion.Reason,
		}
	}
	for _, fact := range report.Facts {
		out.Facts = append(out.Facts, brainBriefJSONFact{
			ID: fact.ID, Paths: fact.Paths, Kind: fact.Kind, Locus: fact.Locus,
			Text: fact.Text, Confidence: fact.Confidence,
		})
	}
	return out
}

func compactSemanticRecords(records []semanticRecord) []compactSemanticRecord {
	if records == nil {
		return []compactSemanticRecord{}
	}
	out := make([]compactSemanticRecord, len(records))
	for i, record := range records {
		out[i] = compactSemanticRecordFrom(record)
	}
	return out
}

func compactSemanticRecordFrom(record semanticRecord) compactSemanticRecord {
	return compactSemanticRecord{
		ID: record.ID, Kind: record.Kind, Name: record.Name, QualifiedName: record.QualifiedName,
package cli

import (
	"os"
	"path/filepath"
	"strings"
)

// brainBriefSemanticFreshnessStats describes the packet-boundary projection,
// not the provider index. A record repeated in two packet sections counts once
// in each section because it consumes packet space (and agent attention) twice.
type brainBriefSemanticFreshnessStats struct {
	InputRecords    int
	KeptRecords     int
	RemovedRecords  int
	RemovedEvidence int
}

func brainBriefSemanticNeedsCurrentBoundary(status brainStatusReport) bool {
	return status.Semantic != nil && brainStatusFreshnessSeverity(status) != "ok"
}

// brainBriefSemanticCandidateLimit is deliberately bounded relative to the
// caller's packet cap. It restores current candidates hidden behind a small
// stale prefix without turning an unsafe index into an unbounded full scan.
func brainBriefSemanticCandidateLimit(requested, indexedSymbols int) int {
	if requested <= 0 {
		return requested
	}
	maxInt := int(^uint(0) >> 1)
	// The semantic stages derive internal scan limits up to candidate*8, so the
	// candidate itself must leave room for that multiplication.
	maxCandidate := maxInt / 8
	if requested >= maxCandidate {
		return maxCandidate
	}
	candidate := requested * 4
	if candidate > maxCandidate {
		candidate = maxCandidate
	}
	if indexedSymbols >= requested && indexedSymbols < candidate {
		candidate = indexedSymbols
	}
	return max(requested, candidate)
}

func brainBriefCapSemantic(semantic *brainBriefSemantic, limit int) {
	if semantic == nil || limit <= 0 {
		return
	}
	semantic.Context.Symbols = capBrainBriefSlice(semantic.Context.Symbols, limit)
	semantic.Context.Neighbors = capBrainBriefSlice(semantic.Context.Neighbors, limit)
	semantic.RuntimeTraces = capBrainBriefSlice(semantic.RuntimeTraces, limit)
	semantic.Tests.Roots = capBrainBriefSlice(semantic.Tests.Roots, limit)
	semantic.Tests.Suggestions = capBrainBriefSlice(semantic.Tests.Suggestions, limit)
	semantic.Tests.synthesisSuggestions = capBrainBriefSlice(semantic.Tests.synthesisSuggestions, limit)
	contextIDs := map[string]struct{}{}
	for _, records := range [][]semanticRecord{semantic.Context.Symbols, semantic.Context.Neighbors} {
		for _, record := range records {
			if record.ID != "" {
				contextIDs[record.ID] = struct{}{}
			}
		}
	}
	relations := make([]semanticRecord, 0, len(semantic.Context.Relations))
	for _, relation := range semantic.Context.Relations {
		if !brainBriefSemanticRelationEndpointsKnown(relation, contextIDs) {
			continue
		}
		relations = append(relations, relation)
	}
	semantic.Context.Relations = capBrainBriefSlice(nonNil(relations), brainBriefSemanticRelationLimit(limit))
}

func brainBriefSemanticRelationLimit(limit int) int {
	maxInt := int(^uint(0) >> 1)
	if limit > maxInt/4 {
		return maxInt
	}
	return limit * 4
}

func capBrainBriefSlice[T any](values []T, limit int) []T {
	if len(values) <= limit {
		return values
	}
	return values[:limit]
}

// brainBriefFilterDepartedSemantic removes indexed semantic records whose
// original slice so no-match and already-good packets remain byte-identical.
func visibleSemanticTestSuggestions(suggestions []semanticTestSuggestion, limit int) []semanticTestSuggestion {
	if limit <= 0 || len(suggestions) == 0 {
		return suggestions
	}
	needsProjection := len(suggestions) > limit
	hasPrimary, hasFallback := false, false
	for _, suggestion := range suggestions {
		switch {
		case suggestion.weak:
			needsProjection = true
		case suggestion.fallback:
			hasFallback = true
		default:
			hasPrimary = true
		}
	}
	needsProjection = needsProjection || (hasPrimary && hasFallback)
	if !needsProjection {
		return suggestions
	}
	out := make([]semanticTestSuggestion, 0, min(limit, len(suggestions)))
	for _, suggestion := range suggestions {
		if suggestion.weak || (hasPrimary && suggestion.fallback) {
			continue
		}
		out = append(out, suggestion)
		if len(out) >= limit {
			break
		}
	}
	return nonNil(out)
}

