        raise ValueError(f"invalid benchmark workspace_name: {name!r}")
    return name


def safe_workspace_name(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    name = value.strip()
    if not re.fullmatch(r"[A-Za-z0-9._-]+", name) or name in {".", ".."} or not name.strip("."):
        return None
    return name


