"""Treatment isolation and task-validity contracts for the agent benchmark.

This module is deliberately deterministic and has no model/runtime dependency so it can be
used by preflight, CI, and evidence verification without running a benchmark agent.
"""

from __future__ import annotations

import datetime as dt
import hashlib
import json
import re
from typing import Any, Callable


TREATMENT_ARMS = {"no_memory", "placebo_packet", "retrieved_memory", "oracle_retrieval"}
QUERY_SOURCES = {"user_query", "oracle_queries"}
REVIEW_DISPOSITIONS = {"approved_symptom_only", "revise", "exclude_oracle_assisted"}
PACKET_START = "<frozen-memory-packet>"
PACKET_END = "</frozen-memory-packet>"


def user_query(task: dict[str, Any]) -> str:
    """Return the agent-visible problem statement, accepting `prompt` only for legacy tasks."""
    value = task.get("user_query", task.get("prompt"))
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"task {task.get('id', '<unknown>')} requires a non-empty user_query")
    return value.strip()


def query_source(task: dict[str, Any]) -> str:
    """Resolve the declared retrieval source; legacy brain_queries never become implicit input."""
    source = task.get("retrieval_query_source", "user_query")
    if source not in QUERY_SOURCES:
        raise ValueError(f"retrieval_query_source must be one of {sorted(QUERY_SOURCES)}, got {source!r}")
    if source == "oracle_queries":
        queries = task.get("oracle_queries")
        if not isinstance(queries, list) or not queries or any(not isinstance(q, str) or not q.strip() for q in queries):
            raise ValueError("retrieval_query_source=oracle_queries requires non-empty oracle_queries")
    return source


def retrieval_query(task: dict[str, Any], source: str | None = None) -> str:
    """Return harness-owned retrieval input. `brain_queries` are intentionally ignored."""
    source = source or query_source(task)
    if source not in QUERY_SOURCES:
        raise ValueError(f"retrieval query source must be one of {sorted(QUERY_SOURCES)}")
    if source == "oracle_queries":
        queries = task.get("oracle_queries")
        if not isinstance(queries, list) or not queries:
            raise ValueError("oracle query source requires oracle_queries")
        return " | ".join(str(q).strip() for q in task["oracle_queries"])
    return user_query(task)


def treatment_for_condition(task: dict[str, Any], condition: str) -> dict[str, Any]:
    """Validate and return one condition's explicit treatment declaration.

    Tasks without `treatments` remain runnable for historical reproduction, but are marked legacy
    and cannot pass confirmatory preflight.
    """
    treatments = task.get("treatments")
    if treatments is None:
        arm = "no_memory" if condition == "no_brain" else "retrieved_memory"
        return {"arm": arm, "query_source": "legacy", "confirmatory_eligible": False}
    if not isinstance(treatments, dict) or not treatments:
        raise ValueError("treatments must be a non-empty condition-to-treatment object")
    raw = treatments.get(condition)
    if not isinstance(raw, dict):
        raise ValueError(f"condition {condition!r} has no explicit treatment declaration")
    unknown = sorted(set(raw) - {
        "arm", "query_source", "seed", "candidate_facts", "solving_fact_ids", "near_duplicate_texts"
    })
    if unknown:
        raise ValueError(f"treatment for {condition!r} has unknown fields: {unknown}")
    arm = raw.get("arm")
    if arm not in TREATMENT_ARMS:
        raise ValueError(f"treatment arm must be one of {sorted(TREATMENT_ARMS)}, got {arm!r}")
    source = raw.get("query_source")
    if source not in QUERY_SOURCES:
        raise ValueError(f"treatment query_source must be one of {sorted(QUERY_SOURCES)}")
    if arm == "oracle_retrieval" and source != "oracle_queries":
        raise ValueError("oracle_retrieval requires query_source=oracle_queries")
    if arm != "oracle_retrieval" and source == "oracle_queries":
        raise ValueError("oracle_queries may only feed the oracle_retrieval arm")
    if source == "oracle_queries":
        retrieval_query(task, source)
    if arm == "placebo_packet":
        if not isinstance(raw.get("seed"), (str, int)) or isinstance(raw.get("seed"), bool):
            raise ValueError("placebo_packet requires a deterministic string or integer seed")
        facts = raw.get("candidate_facts")
        if not isinstance(facts, list) or not facts:
            raise ValueError("placebo_packet requires non-empty candidate_facts")
    return {**raw, "confirmatory_eligible": arm != "oracle_retrieval"}


def treatment_schema_errors(task: dict[str, Any], conditions: list[str] | set[str]) -> list[str]:
    errors: list[str] = []
    if task.get("memory_delivery") != "frozen_brief":
        errors.append("explicit comparable treatments require memory_delivery=frozen_brief")
    if "user_query" not in task:
        errors.append("explicit schema requires user_query (legacy prompt is exploratory-only)")
    if "retrieval_query_source" not in task:
        errors.append("explicit schema requires retrieval_query_source")
    if "treatments" not in task:
        errors.append("explicit schema requires treatments")
    for condition in sorted(conditions):
        try:
            treatment = treatment_for_condition(task, condition)
            if treatment["arm"] == "oracle_retrieval":
                errors.append(f"condition {condition!r} is oracle_retrieval and is excluded from confirmatory suites")
        except ValueError as exc:
            errors.append(str(exc))
    return errors


def normalize_prompt_for_parity(prompt: str) -> str:
    """Remove only the packet payload block, leaving its stable presence marker."""
    pattern = re.compile(
        rf"{re.escape(PACKET_START)}.*?{re.escape(PACKET_END)}",
        re.DOTALL,
    )
    return pattern.sub(f"{PACKET_START}\n<packet-payload>\n{PACKET_END}", prompt)


def prompt_parity(prompts: dict[str, str]) -> dict[str, Any]:
    normalized = {condition: normalize_prompt_for_parity(prompt) for condition, prompt in prompts.items()}
    hashes = {
        condition: hashlib.sha256(value.encode("utf-8")).hexdigest()
        for condition, value in normalized.items()
    }
    return {"ok": len(set(normalized.values())) <= 1, "normalized_sha256": hashes}


def _fact_id(fact: dict[str, Any]) -> str:
    return str(fact.get("id") or fact.get("fact_id") or "")


def _fact_text(fact: dict[str, Any]) -> str:
    return str(fact.get("text") or fact.get("content") or "")


def packet_fact_ids(packet: str | dict[str, Any]) -> list[str]:
    """Extract stable fact/result IDs from supported search packet shapes."""
    payload = json.loads(packet) if isinstance(packet, str) else packet
    results = payload.get("results", []) if isinstance(payload, dict) else []
    ids: list[str] = []
    for result in results:
        if not isinstance(result, dict):
            continue
        nested_fact = result.get("fact") if isinstance(result.get("fact"), dict) else {}
        provenance = result.get("provenance") if isinstance(result.get("provenance"), dict) else {}
        value = result.get("fact_id") or nested_fact.get("id") or provenance.get("fact_id") or result.get("id")
        if value:
            ids.append(str(value))
    return ids


def _normalized_terms(text: str) -> set[str]:
    return {token for token in re.findall(r"[a-z0-9]+", text.casefold()) if len(token) >= 3}


def _near_duplicate(left: str, right: str) -> bool:
    a, b = _normalized_terms(left), _normalized_terms(right)
    if not a or not b:
        return False
    return len(a & b) / len(a | b) >= 0.72


def _fact_timestamp(fact: dict[str, Any]) -> dt.datetime | None:
    value = fact.get("created_at", fact.get("timestamp"))
    if not value:
        return None
    try:
        parsed = dt.datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    """Derive quality only from predeclared output criteria.

    Agent process behavior (running tests or checking a diff), runtime, token
    use, and treatment-specific tool use remain diagnostics and cannot improve
    the co-primary quality endpoint.
    """
    reasons: list[str] = []
    if not validation_ok:
        reasons.append("validation_failed")
    if returncode != 0:
        reasons.append("agent_returncode_nonzero")
    forbidden = (scoring.get("details") or {}).get("forbidden_files_touched")
    if isinstance(forbidden, list) and forbidden:
        reasons.append("forbidden_file_modified")
    reasons.extend(
        f"{name}_failed" for name, passed in sorted(integrity_audits.items()) if passed is not True
    )
    # Only outcome (45) and patch focus (30) measure the produced patch. The
    # process-behavior validation_discipline component is treatment-responsive
    # and therefore deliberately excluded with runtime and tool-use points.
    raw_core = sum(
        float(scoring.get(key) or 0)
        for key in ("outcome", "patch_focus")
    )
    normalized = max(0.0, min(1.0, raw_core / 75.0))
    critical = bool(reasons)
    return {
        "schema": CONFIRMATORY_QUALITY_SCHEMA,
        "rubric": "task_relative_output_outcome_patch_focus_v2",
        "task_normalized_score": 0.0 if critical else round(normalized, 12),
        "critical_failure": critical,
        "critical_failure_reasons": reasons,
        "excluded_components": [
            "validation_discipline",
            "runtime_efficiency",
            "brain_use",
        ],
    }


def treatment_timeout_stage(
    user_visible_interval_started: float | None,
    agent_interval_started: float | None,
) -> str | None:
    """Classify a subprocess timeout relative to the causal treatment boundary."""
    if user_visible_interval_started is None:
        return None
    if agent_interval_started is None:
        return "treatment_retrieval_or_delivery"
    return "agent_execution"


def run_one(
    task: dict[str, Any],
    runner: RunnerSpec,
    condition: str,
    repetition: int,
    suite_dir: pathlib.Path,
    tools: dict[str, pathlib.Path],
    args: argparse.Namespace,
    pricing: dict[str, Any],
) -> RunResult:
    cell_started = time.monotonic()
    agent_interval_started: float | None = None
    agent_interval_wall_seconds: float | None = None
    user_visible_interval_started: float | None = None
    user_visible_interval_wall_seconds: float | None = None
    causal_outcome_finished_monotonic: float | None = None
    run_agent_entered = False
    timeout_occurred = False
    timeout_stage: str | None = None
    timeout_component_limit_seconds: float | None = None
    task, source, base_provenance = bind_task_base_commit(task)
    run_id = f"{task['id']}__{runner.id}__{condition}__r{repetition}"
    run_dir = suite_dir / run_id
    run_dir.mkdir(parents=True, exist_ok=False)
    cache_policy = getattr(args, "cache_policy", "isolated_per_cell")
    cell_cache_paths = runtime_cache_paths(suite_dir, run_dir, cache_policy)
    runtime_env = ensure_runtime_cache(cell_cache_paths)
    worktree: pathlib.Path | None = None
    record: dict[str, Any] = {
        "run_id": run_id,
        "task_id": task["id"],
        "repo": task["repo"],
        "agent": runner.agent,
        "runner": {
            "id": runner.id,
            "agent": runner.agent,
            "model": runner.model,
            "effort": runner.effort,
        },
        "condition": condition,
        "repetition": repetition,
        "treatment_started": False,
        "agent_ran": False,
        "started_at": dt.datetime.now(dt.UTC).isoformat(),
        "planned_ordinal": getattr(args, "planned_ordinal", None),
        "runtime_controls": {
            "cache_policy": cache_policy,
            "cache_paths": cache_path_provenance(suite_dir, cell_cache_paths),
            "ambient_go_cache_inherited": False,
            "timing_definitions": TIMING_DEFINITIONS,
        },
        "provenance": build_record_provenance(
            task,
            runner,
            condition,
            repetition,
            suite_dir,
            tools,
            args,
            command="run",
            source=source,
            base=base_provenance,
        ),
    }
    try:
        record["delivery_mode"] = "harness" if uses_frozen_brain_delivery(task) else "agent_tool"
        treatment = treatment_for_condition(task, condition)
        record["treatment"] = {key: value for key, value in treatment.items() if key != "candidate_facts"}
        record["retrieval_query_source"] = treatment["query_source"]
        record["task_validity"] = task_validity_lint(task, brain_query_leak_audit)
        worktree = create_worktree(task, run_dir)
        worktree_sanitization = sanitize_agent_worktree(worktree, task)
        record["agent_worktree_sanitization"] = worktree_sanitization
        record["agent_baseline_history"] = agent_history_attestation(
            worktree,
            filtered_agent_history_paths(task),
        )
        if not record["agent_baseline_history"]["repository_isolated"]:
            raise RuntimeError(
                "agent repository isolation failed: "
                f"{record['agent_baseline_history']}"
            )
        prepare_condition_history(task, condition, worktree)
        env, prep = prepare_brain(
            task,
            condition,
            worktree,
            run_dir,
            tools,
            args.checkpoint_limit,
            use_cache=not args.no_brain_cache,
            refresh_cache=args.refresh_brain_cache,
            runtime_env=runtime_env,
        )
        memory_packet: str | None = None
        # frozen_brief arms have no worktree brain (see prepare_brain short-circuit); their
        # readiness is verified via the delivered frozen packet, not a worktree manifest.
        needs_worktree_brain = condition != "no_brain" and not uses_frozen_brain_delivery(task)
        brain_state = collect_brain_state(worktree, env, tools) if needs_worktree_brain else {}
        if needs_worktree_brain:
            assert_brain_state_ready(task, condition, brain_state)
        post_brain_changed = apply_post_brain_setup(task, worktree)
        if post_brain_changed:
            record["post_brain_baseline_history"] = commit_agent_baseline(
                worktree,
                f"Benchmark post-brain agent baseline for {task['id']}",
                include_current_changes=True,
                private_paths=filtered_agent_history_paths(task),
            )
        record["go_dependency_prewarm"] = prewarm_go_dependencies(worktree, env)
        agent_visible_entire_removed = False
        if should_remove_agent_visible_entire_history(task, condition):
            agent_visible_entire_removed = remove_agent_visible_entire_history(worktree)
        record["agent_runtime_history"] = agent_history_attestation(
            worktree,
            filtered_agent_history_paths(task),
        )
        if not record["agent_runtime_history"]["repository_isolated"]:
            raise RuntimeError(
                "agent runtime repository isolation failed: "
                f"{record['agent_runtime_history']}"
            )
        secret_preflight = agent_secret_preflight(worktree)
        record["agent_secret_preflight"] = secret_preflight
        if not secret_preflight["ok"]:
            raise RuntimeError(f"agent-visible benchmark secrets failed preflight: {secret_preflight['findings'][:3]}")
        # OPT-IN diagnostic only (ENTIRE_BENCH_CAPTURE_BRIEF=1): off by default so normal runs
        # add zero extra `entire brain brief` subprocess/overhead and no run_dir packet. When
        # enabled (debugging delivery), capture against the SAME worktree state the agent's own
        # brief will see — after post-brain setup (which injects the regression for tasks that
        # defer it) and agent-history reset — so the packet's live-state overlay matches.
        if condition != "no_brain" and os.environ.get("ENTIRE_BENCH_CAPTURE_BRIEF") == "1":
            capture_brief_packet(task, condition, runner, worktree, env, tools, run_dir)
        # The co-primary user-visible timer begins at the causal treatment
        # boundary. All setup and secret checks above are excluded; retrieved
        # and placebo arms now include their actual harness-owned retrieval and
        # packet delivery cost, while no-memory executes the same logical no-op.
        user_visible_interval_started = time.monotonic()
        record["treatment_started"] = True
        if task.get("treatments"):
            memory_packet, packet_artifact = treatment_memory_packet(task, condition, worktree, tools)
            record["packet_artifact"] = {"path": None, **packet_artifact}
            if memory_packet is not None:
                (run_dir / "packet.txt").write_text(memory_packet)
                record["packet_artifact"]["path"] = "packet.txt"
        prompt = prompt_for(task, condition, runner, memory_packet=memory_packet)
        (run_dir / "prompt.txt").write_text(prompt)
        record["prompt_artifact"] = {
            "path": "prompt.txt",
            "sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
            "bytes": len(prompt.encode("utf-8")),
        }
        agent_interval_started = time.monotonic()
        run_agent_entered = True
