        "git rev-parse HEAD^@",
        "git show HEAD^@",
        "git diff ORIG_HEAD",
        "git diff HEAD@{1}",
        "git reflog -p",
        "git log -g -p",
        "git show --format=%P --no-patch HEAD",
        "git cat-file -p HEAD",
        "git show -m HEAD",
