// rebuildHistoryFTSFromTruth force-replaces a corrupt derived payload after the
// authoritative JSON index has been verified and loaded. Normal stale caches use
// openHistoryFTS's cheaper double-checked rebuild; this path is only for a v2
// database whose metadata claimed freshness but whose hydrated rows were invalid.
func rebuildHistoryFTSFromTruth(brainDir string, index historyIndex) error {
	return withBrainWriteLock(brainDir, func() error {
		path, err := prepareBrainRelativeSQLiteFile(brainDir, historyFTSDBRelPath())
		if err != nil {
			return err
		}
		db, err := sql.Open(sqliteDriverName, path)
		if err != nil {
			return err
		}
		defer db.Close()
		db.SetMaxOpenConns(1)
		for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA journal_mode=WAL;"} {
			if _, err := db.Exec(pragma); err != nil {
				return err
			}
		}
		return buildHistoryFTS(db, index)
	})
}

// validateHistoryFTSDirectSource establishes the authoritative side of the
// no-JSON-read contract. The manifest must carry a strong record identity and
// exact index-file metadata produced by refresh. We require the declared truth
// to remain a safe regular file and compare its size without reading it. A size
// mismatch is resolved by the bounded publication-race logic in the caller:
// refresh writes the next JSON generation before committing its FTS transaction,
// so an old reader may use the matching old FTS only while the writer lock proves
// that publication is in progress. The exact checksum is verified on the full
// JSON path.
func validateHistoryFTSDirectSource(brainDir string, source *historySourceManifest) (historyFTSIdentity, bool, bool, error) {
	identity, ok := historyFTSIdentityFromSource(source)
	if !ok || source.IndexBytes <= 0 || !validHistorySHA256(source.IndexSHA256) {
		return historyFTSIdentity{}, false, false, nil // legacy source: use the verified full-index path
	}
	clean, err := validateHistoryIndexPath(source.IndexPath)
	if err != nil {
		return historyFTSIdentity{}, false, false, err
	}
	if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
		return historyFTSIdentity{}, false, false, err
	}
	path := filepath.Join(brainDir, clean)
	if err := rejectUnsafeExistingRegularFile(path, "history index"); err != nil {
		return historyFTSIdentity{}, false, false, err
	}
	info, err := os.Stat(path)
	if err != nil {
		return historyFTSIdentity{}, false, false, err
	}
	if !info.Mode().IsRegular() {
		return historyFTSIdentity{}, false, false, fmt.Errorf("history index must be a regular file: %s", source.IndexPath)
	}
	return identity, true, info.Size() == source.IndexBytes, nil
}

// openHistoryFTSReadOnly opens only an already-present, safe derived cache. It
// never creates directories/files and never changes journal mode on the query
// path. Unsafe or absent SQLite artifacts are cache misses; the authoritative
// JSON fallback decides whether the user-visible request can still succeed.
func openHistoryFTSReadOnly(brainDir string) (*sql.DB, error) {
	if err := rejectSymlinkedBrainRoot(brainDir); err != nil {
		return nil, err
	}
	clean, err := cleanBrainRelativePath(historyFTSDBRelPath())
	if err != nil {
		return nil, err
	}
	if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
		return nil, err
	}
	path := filepath.Join(brainDir, clean)
	for _, candidate := range []string{path, path + "-wal", path + "-shm", path + "-journal"} {
		if err := rejectUnsafeExistingRegularFile(candidate, "history sqlite cache"); err != nil {
			return nil, err
		}
	}
	dsn := (&url.URL{Scheme: "file", Path: path, RawQuery: "mode=ro"}).String()
	db, err := sql.Open(sqliteDriverName, dsn)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA query_only=ON;"} {
		if _, err := db.Exec(pragma); err != nil {
			db.Close()
			return nil, err
		}
	}
	return db, nil
}

// rankHistoryViaFreshFTS hydrates BM25 matches directly from schema-v2 SQLite
// payload rows. Metadata validation and ranking share one read transaction, so
// a concurrent refresh cannot commit a new generation between the two reads.
// used=false is a soft cache miss and requires the caller to load index.json;
// used=true includes an honest empty result.
func rankHistoryViaFreshFTS(brainDir string, source *historySourceManifest, kind, query string, limit int) ([]scoredHistoryRecord, bool, error) {
	return rankHistoryViaFreshFTSCutoff(brainDir, source, kind, query, limit, historyFTSRelevanceCutoff)
}

type historyFTSDirectRetry int

var errHistoryFTSPayloadCorrupt = errors.New("history fts payload is corrupt")

const (
	historyFTSDirectNoRetry historyFTSDirectRetry = iota
	historyFTSDirectReloadManifest
	historyFTSDirectWaitForPublication
)

func rankHistoryViaFreshFTSCutoff(brainDir string, source *historySourceManifest, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool, error) {
	out, used, err := rankHistoryViaFreshFTSCutoffDetailed(brainDir, source, kind, query, limit, cutoff)
	if errors.Is(err, errHistoryFTSPayloadCorrupt) {
		return nil, false, nil // derived-cache corruption is always a soft miss
	}
	return out, used, err
}

func rankHistoryViaFreshFTSCutoffDetailed(brainDir string, source *historySourceManifest, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool, error) {
	out, used, retry, err := rankHistoryViaFreshFTSCutoffOnce(brainDir, source, kind, query, limit, cutoff)
	if err != nil || retry == historyFTSDirectNoRetry {
		return out, used, err
	}
	current, err := currentHistorySource(brainDir)
	if err != nil {
		return nil, false, err
	}
	if !sameHistoryDirectSource(source, current) {
		out, used, _, err = rankHistoryViaFreshFTSCutoffOnce(brainDir, current, kind, query, limit, cutoff)
		return out, used, err
	}
	if retry == historyFTSDirectReloadManifest {
		return nil, false, nil // ordinary stale/corrupt derived cache
	}

	// index.json is a different size while the caller still holds the old
	// manifest. This is either a refresh publication window or out-of-band
	// corruption. Wait once on the writer lock as a publication barrier, then
	// re-read the manifest. The normal long rebuild path never waits here: while
	// it runs, the old committed FTS metadata still matches and the read proceeds.
	unlock, lockErr := acquireBrainWriteLock(brainDir)
	if lockErr != nil {
		return nil, false, lockErr
	}
	unlock()
	current, err = currentHistorySource(brainDir)
	if err != nil {
		return nil, false, err
	}
	if !sameHistoryDirectSource(source, current) {
		out, used, _, err = rankHistoryViaFreshFTSCutoffOnce(brainDir, current, kind, query, limit, cutoff)
		return out, used, err
	}
	return nil, false, errors.New("history index size does not match manifest")
}

func currentHistorySource(brainDir string) (*historySourceManifest, error) {
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return nil, err
	}
	if manifest.Sources == nil || manifest.Sources.History == nil {
		return nil, errors.New("history source missing after manifest reload")
	}
	return manifest.Sources.History, nil
}

func sameHistoryDirectSource(a, b *historySourceManifest) bool {
	if a == nil || b == nil {
		return a == b
	}
	return a.IndexPath == b.IndexPath && a.IndexBytes == b.IndexBytes && a.IndexSHA256 == b.IndexSHA256 &&
		a.RecordsFingerprint == b.RecordsFingerprint && a.Records == b.Records
}

func historyBrainWriteInProgress(brainDir string) (bool, error) {
	unlock, err := acquireBrainWriteLockTimeout(brainDir, 0)
	if err == nil {
		unlock()
		return false, nil
	}
	if strings.Contains(err.Error(), "brain_locked:") {
		return true, nil
	}
	return false, err
}

func rankHistoryViaFreshFTSCutoffOnce(brainDir string, source *historySourceManifest, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool, historyFTSDirectRetry, error) {
	if limit <= 0 {
		return nil, false, historyFTSDirectNoRetry, nil
	}
	expr := historyFTSMatchExpr(query)
	if expr == "" {
		return nil, false, historyFTSDirectNoRetry, nil
	}
	identity, eligible, sizeMatches, err := validateHistoryFTSDirectSource(brainDir, source)
	if err != nil || !eligible {
		return nil, false, historyFTSDirectNoRetry, err
	}
	db, err := openHistoryFTSReadOnly(brainDir)
	if err != nil {
		if !sizeMatches {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
		return nil, false, historyFTSDirectNoRetry, nil
	}
	defer db.Close()
	tx, err := db.Begin()
	if err != nil {
		if !sizeMatches {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
		return nil, false, historyFTSDirectNoRetry, nil
	}
	defer tx.Rollback()
	if !historyFTSFreshIdentity(tx, identity) {
		if !sizeMatches {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
		return nil, false, historyFTSDirectReloadManifest, nil
	}
	if !sizeMatches {
		writing, lockErr := historyBrainWriteInProgress(brainDir)
		if lockErr != nil {
			return nil, false, historyFTSDirectNoRetry, lockErr
		}
		if !writing {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
	}

	args := []any{expr}
	var sb strings.Builder
	sb.WriteString(`SELECT r.fts_rowid, r.rec_order, r.id, r.kind, r.branch, r.path, r.line, r.summary, r.terms_json, bm25(history_fts)
		FROM history_fts JOIN history_records r ON r.fts_rowid = history_fts.rowid
		WHERE history_fts MATCH ?`)
	appendHistoryFTSKindFilter(&sb, &args, kind, "r.kind")
	sb.WriteString(" ORDER BY bm25(history_fts) LIMIT ?")
	args = append(args, limit*4)

	rows, err := tx.Query(sb.String(), args...)
	if err != nil {
		if !sizeMatches {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
		return nil, false, historyFTSDirectNoRetry, nil
	}
	out := make([]scoredHistoryRecord, 0, limit)
	seen := map[string]struct{}{}
	seenOrders := map[int]struct{}{}
	seenIDs := map[string]struct{}{}
	var topScore float64
	valid := true
	for rows.Next() {
		var rec historyRecord
		var ftsRowID int
		var order int
		var termsJSON string
		var bm float64
		if err := rows.Scan(&ftsRowID, &order, &rec.ID, &rec.Kind, &rec.Branch, &rec.Path, &rec.Line, &rec.Summary, &termsJSON, &bm); err != nil {
			valid = false
			break
		}
		if order < 0 || order >= identity.RecordCount || ftsRowID != order+1 || rec.ID == "" || len(termsJSON) > historyMaxLineBytes*4 {
			valid = false
			break
		}
		if _, duplicate := seenOrders[order]; duplicate {
			valid = false
			break
		}
		if _, duplicate := seenIDs[rec.ID]; duplicate {
			valid = false
			break
		}
		seenOrders[order] = struct{}{}
		seenIDs[rec.ID] = struct{}{}
		if termsJSON != "null" {
			if err := json.Unmarshal([]byte(termsJSON), &rec.Terms); err != nil {
				valid = false
				break
			}
			if len(rec.Terms) == 0 {
				rec.Terms = nil
			}
		}
		score := -bm
		if topScore == 0 {
			topScore = score
		} else if score < cutoff*topScore {
			break
		}
		key := normalizeHistorySearchText(rec.Summary)
		if _, duplicate := seen[key]; duplicate {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, scoredHistoryRecord{Record: rec, Score: int(score*1000 + 0.5), Order: order})
		if len(out) >= limit {
			break
		}
	}
	if err := rows.Err(); err != nil {
		valid = false
	}
	if err := rows.Close(); err != nil {
		valid = false
	}
	if !valid {
		if !sizeMatches {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
		return nil, false, historyFTSDirectNoRetry, errHistoryFTSPayloadCorrupt
	}
	if err := tx.Commit(); err != nil {
		if !sizeMatches {
			return nil, false, historyFTSDirectWaitForPublication, nil
		}
		return nil, false, historyFTSDirectNoRetry, nil
	}
	return out, true, historyFTSDirectNoRetry, nil
}

func appendHistoryFTSKindFilter(sb *strings.Builder, args *[]any, kind, column string) {
	if allowed := historyInspectKinds(kind); len(allowed) > 0 {
		kinds := make([]string, 0, len(allowed))
		for k := range allowed {
			kinds = append(kinds, k)
		}
		sort.Strings(kinds)
		placeholders := make([]string, len(kinds))
		for i, k := range kinds {
			placeholders[i] = "?"
			*args = append(*args, k)
		}
		sb.WriteString(" AND " + column + " IN (" + strings.Join(placeholders, ",") + ")")
		return
	}
	sb.WriteString(" AND " + column + " != 'request'")
}

const (
	historyIndexAccessFTSPayload = "fts_payload"
	historyIndexAccessJSON       = "index_json"
)

type historyIndexLoadFunc func(string, *historySourceManifest) (historyIndex, error)

func rankHistoryLexicalFromSource(brainDir string, source *historySourceManifest, kind, query string, limit int) ([]scoredHistoryRecord, string, int, error) {
	return rankHistoryLexicalFromSourceWithLoader(brainDir, source, kind, query, limit, loadBrainHistoryIndex)
}

func rankHistoryLexicalFromSourceWithLoader(brainDir string, source *historySourceManifest, kind, query string, limit int, loader historyIndexLoadFunc) ([]scoredHistoryRecord, string, int, error) {
	scored, used, directErr := rankHistoryViaFreshFTSCutoffDetailed(brainDir, source, kind, query, limit, historyFTSRelevanceCutoff)
	derivedCorrupt := errors.Is(directErr, errHistoryFTSPayloadCorrupt)
	if directErr != nil && !derivedCorrupt {
		return nil, "", 0, directErr
	} else if used {
		return scored, historyIndexAccessFTSPayload, source.Records, nil
	}
	index, err := loader(brainDir, source)
	if err != nil {
		return nil, "", 0, err
	}
	if derivedCorrupt {
		if rebuildErr := rebuildHistoryFTSFromTruth(brainDir, index); rebuildErr == nil {
			if rebuilt, ok := rankHistoryViaFTS(brainDir, index, kind, query, limit); ok {
				scored = rebuilt
			} else {
				scored = rankHistoryRecordsScored(index, kind, query, limit, 0)
			}
		} else {
			scored = rankHistoryRecordsScored(index, kind, query, limit, 0)
		}
	} else {
		var ok bool
		scored, ok = rankHistoryViaFTS(brainDir, index, kind, query, limit)
		if !ok {
			scored = rankHistoryRecordsScored(index, kind, query, limit, 0)
		}
	}
	return scored, historyIndexAccessJSON, len(index.Records), nil
}

// rankHistoryViaFTS ranks records with the BM25 index, returning ok=false on any
// failure (or a degenerate query) so the caller falls back to the substring
// scorer. It dedups by normalized summary like the scorer does. NOTE on the sign:
// SQLite FTS5 bm25() is the BM25 score *negated* (per the FTS5 docs), so a better
// match is MORE NEGATIVE and `ORDER BY bm25()` ASC returns best-first. We negate it
// back to a positive display score (higher = better) for the cutoff and Score.
func rankHistoryViaFTS(brainDir string, index historyIndex, kind, query string, limit int) ([]scoredHistoryRecord, bool) {
	return rankHistoryViaFTSCutoff(brainDir, index, kind, query, limit, historyFTSRelevanceCutoff)
}

// rankHistoryViaFTSCutoff is rankHistoryViaFTS with the relevance cutoff as a
// parameter, so the history eval can sweep it (the shipped 0.30 was chosen by
// inspection, "tunable once a history eval lands"). Production callers go
// through rankHistoryViaFTS and always get the shipped constant.
func rankHistoryViaFTSCutoff(brainDir string, index historyIndex, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool) {
	if limit <= 0 {
		return nil, false
	}
	expr := historyFTSMatchExpr(query)
	if expr == "" {
		return nil, false
	}
	db, err := openHistoryFTS(brainDir, index)
	if err != nil {
		return nil, false
	}
	defer db.Close()

	args := []any{expr}
	var sb strings.Builder
	sb.WriteString(`SELECT r.rec_order, bm25(history_fts)
		FROM history_fts JOIN history_records r ON r.fts_rowid = history_fts.rowid
		WHERE history_fts MATCH ?`)
	"why": true, "with": true, "would": true,
}

func historyQueryStopword(term string) bool {
	if genericQueryStopwords[term] {
		return true
	}
	// History/semantic-search-specific noise words layered on the generic set:
	// natural-language filler plus domain verbs/nouns ("regression", "preserve",
	// "restore", ...) that carry no signal for a free-text record search.
	switch term {
	case "a", "an", "as", "at", "be", "been", "by", "current", "do",
		"during", "existing", "in", "is", "it", "keep", "local", "of", "on",
		"only", "or", "other", "previous", "prior", "preserve", "regression",
		"restore", "same", "task", "to", "without":
		return true
	case "behavior", "entire", "fresh", "parent", "setting", "value", "values":
		return true
	case "done", "over", "instead", "we", "our", "could", "about":
		return true
	default:
		return false
	}
}

func loadBrainHistoryIndex(brainDir string, source *historySourceManifest) (historyIndex, error) {
	data, err := readBrainHistoryIndex(brainDir, source)
	if err != nil {
		return historyIndex{}, err
	}
	return decodeBrainHistoryIndex(data, source)
}

// loadBrainHistoryIndexWithLegacyIdentity returns the same verified index as
// loadBrainHistoryIndex plus an optional identity upgrade derived from the
// exact byte slice that was parsed. Older manifests predate the strong source
// identity fields required by direct FTS hydration. Keeping hashing and parsing
// on one immutable slice prevents a path replacement from producing a hash of
// generation A and parsed records from generation B.
func loadBrainHistoryIndexWithLegacyIdentity(brainDir string, source *historySourceManifest) (historyIndex, *historyLegacyIdentity, error) {
	data, err := readBrainHistoryIndex(brainDir, source)
	if err != nil {
		return historyIndex{}, nil, err
	}
	index, err := decodeBrainHistoryIndex(data, source)
	if err != nil {
		return historyIndex{}, nil, err
	}
	legacyIdentity := deriveHistoryLegacyIdentity(source, data, index)
	if legacyIdentity != nil {
		// The direct/index-backed FTS freshness check consumes this private
		// identity. It is derived from the parsed truth, not trusted from a
		// legacy manifest, and avoids recomputing it later in this same request.
		index.recordsFingerprint = legacyIdentity.RecordsFingerprint
	}
	return index, legacyIdentity, nil
}

func readBrainHistoryIndex(brainDir string, source *historySourceManifest) ([]byte, error) {
	if source == nil || source.IndexPath == "" {
		return nil, errors.New("history index missing; run `entire brain refresh`")
	}
	clean, err := validateHistoryIndexPath(source.IndexPath)
	if err != nil {
		return nil, err
	}
	if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(filepath.Join(brainDir, clean))
	if err != nil {
		return nil, err
	}
	return data, nil
}

func decodeBrainHistoryIndex(data []byte, source *historySourceManifest) (historyIndex, error) {
	if source.IndexBytes > 0 && int64(len(data)) != source.IndexBytes {
		return historyIndex{}, fmt.Errorf("history index size mismatch: got %d bytes, manifest declares %d", len(data), source.IndexBytes)
	}
	if source.IndexSHA256 != "" && historyIndexBytesFingerprint(data) != source.IndexSHA256 {
		return historyIndex{}, errors.New("history index checksum does not match manifest")
	}
	var index historyIndex
	if err := json.Unmarshal(data, &index); err != nil {
		return historyIndex{}, err
	}
	if source.RecordsFingerprint != "" {
		if !validHistorySHA256(source.RecordsFingerprint) {
			return historyIndex{}, errors.New("history records fingerprint is invalid")
		}
		if len(index.Records) != source.Records {
			return historyIndex{}, fmt.Errorf("history record count mismatch: got %d, manifest declares %d", len(index.Records), source.Records)
		}
		if !source.GeneratedAt.IsZero() && !index.GeneratedAt.Equal(source.GeneratedAt) {
			return historyIndex{}, errors.New("history index generation does not match manifest")
		}
		// IndexSHA256 binds the exact serialized record set to this manifest.
		// Recomputing the canonical per-record hash here would marshal hundreds
		// of thousands of records on every semantic/get path; the exact byte
		// checksum above already provides the integrity check we need.
		index.recordsFingerprint = source.RecordsFingerprint
	}
	return index, nil
}

func validateHistoryIndexPath(indexPath string) (string, error) {
	clean := filepath.Clean(filepath.FromSlash(indexPath))
	cleanSlash := filepath.ToSlash(clean)
	if cleanSlash != indexPath {
		return "", fmt.Errorf("history index_path must be canonical: %s", indexPath)
	}
	if strings.HasPrefix(clean, ".."+string(filepath.Separator)) || filepath.IsAbs(clean) || cleanSlash != historyIndexPath {
		return "", fmt.Errorf("history index_path is unsafe: %s", indexPath)
	}
	return clean, nil

// historyIndexProgress reports incremental progress while the history index is
// rebuilt. done counts session files processed so far out of total. It is
// optional; pass nil when no progress reporting is needed.
type historyIndexProgress func(done, total int)

func writeBrainHistoryIndexAndSource(outputDir string, now time.Time, progress historyIndexProgress) (*historySourceManifest, error) {
	var source *historySourceManifest
	err := withBrainWriteLock(outputDir, func() error {
		var runErr error
		source, runErr = writeBrainHistoryIndexAndSourceLocked(outputDir, now, progress)
		return runErr
	})
	return source, err
}

func writeBrainHistoryIndexAndSourceLocked(outputDir string, now time.Time, progress historyIndexProgress) (*historySourceManifest, error) {
	index, source, err := buildBrainHistoryIndex(outputDir, now, progress)
	if err != nil {
		return nil, err
	}
	data, err := json.MarshalIndent(index, "", "  ")
	if err != nil {
		return nil, err
	}
	data = append(data, '\n')
	source.IndexBytes = int64(len(data))
	source.IndexSHA256 = historyIndexBytesFingerprint(data)
	source.RecordsFingerprint = historyRecordsFingerprint(index.Records)
	index.recordsFingerprint = source.RecordsFingerprint
	if err := writeBrainRelativeFileAtomic(outputDir, historyIndexPath, data, 0o600); err != nil {
		return nil, fmt.Errorf("write history index: %w", err)
	}
	// Build the derived BM25 index alongside its truth so the search/query verbs
	// do not pay a first-query rebuild. Best-effort: the query path rebuilds it
	// lazily on any failure, so this must never fail the refresh.
	if db, ftsErr := openHistoryFTSLocked(outputDir, index); ftsErr == nil {
		_ = db.Close()
	}
	manifest, err := loadBrainManifest(outputDir)
	if err != nil {
		return nil, err
	}
	if manifest.Sources == nil {
		manifest.Sources = &brainSources{}
	}
	manifest.Sources.History = source
	if manifest.GeneratedAt.IsZero() {
		manifest.GeneratedAt = now
	}
	if err := writeBrainManifestAndReadme(outputDir, *manifest); err != nil {
		return nil, err
	}
	return source, nil
}

// historyRecordsFingerprint is the content identity shared by history/index.json
// and its derived indexes. It covers every record field in stable record order,
// while deliberately excluding generation time and warnings: neither changes
// retrieval content. Empty and nil term slices have the same JSON representation
// in index.json (omitempty), so canonicalize them to the same identity here too.
func historyRecordsFingerprint(records []historyRecord) string {
	h := sha256.New()
	_, _ = io.WriteString(h, "entire-brain/history-records/v1\x00")
	_, _ = io.WriteString(h, strconv.Itoa(len(records))+"\x00")
	for _, record := range records {
		if len(record.Terms) == 0 {
			record.Terms = nil
		}
		data, err := json.Marshal(record)
		if err != nil {
			return ""
		}
		_, _ = io.WriteString(h, strconv.Itoa(len(data))+":")
		_, _ = h.Write(data)
	}
	return "sha256:" + hex.EncodeToString(h.Sum(nil))
}

func historyIndexBytesFingerprint(data []byte) string {
	sum := sha256.Sum256(data)
	return "sha256:" + hex.EncodeToString(sum[:])
}

func buildBrainHistoryIndex(outputDir string, now time.Time, progress historyIndexProgress) (historyIndex, *historySourceManifest, error) {
	sessionsRoot := filepath.Join(outputDir, exportSessionsDirectory)
	index := historyIndex{GeneratedAt: now}
	if _, err := os.Stat(sessionsRoot); err != nil {
		if os.IsNotExist(err) {
			return index, nil, errors.New("session history missing; run `entire brain refresh sessions` first")
		}
		return index, nil, err
	}
	prevCache := loadHistoryScanCache(outputDir)
	var files []historySessionCandidate
	if len(prevCache.Files) == 0 {
		// A cache-empty rebuild needs every transcript parsed. Collect metadata
		// only so parsing and SHA-256 can share one forward-only file read.
		var err error
		files, err = collectHistorySessionFileCandidates(sessionsRoot, &index.Warnings)
		if err != nil {
			return index, nil, err
		}
	} else {
		// Preserve v6's hash-only cache-hit path exactly. Content SHA remains the
		// authority, including for same-size/restored-mtime rewrites.
		hashed, err := collectHistorySessionFiles(sessionsRoot, &index.Warnings)
		if err != nil {
			return index, nil, err
		}
		files = make([]historySessionCandidate, 0, len(hashed))
		for _, file := range hashed {
			files = append(files, historySessionCandidate{historySessionFile: file})
		}
	}
	newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
	manifest, _ := loadBrainManifest(outputDir)
	branchByPath := historyBranchByTranscriptPath(manifest)
	// On a cache-empty build, total is the metadata-eligible candidate set.
	// Every candidate advances progress exactly once even when a later open or
	// identity check fails. Only complete identity-stable reads are fingerprinted;
	// only clean parses are cached and indexed. Walk warnings retain walk order,
	// while per-file failures follow this recency-sorted scan order.
	fingerprintedFiles := make([]historySessionFile, 0, len(files))

	total := len(files)
	if progress != nil {
		progress(0, total)
	}
	seenDecisions := map[string]struct{}{}
	for i, file := range files {
		rel, relErr := filepath.Rel(outputDir, file.Path)
		if relErr != nil {
			rel = file.Path
		}
		rel = filepath.ToSlash(rel)

		var records []historyRecord
		cached, hasCached := prevCache.Files[rel]
		if file.ContentSHA256 != "" {
			fingerprintedFiles = append(fingerprintedFiles, file.historySessionFile)
			if hasCached && cached.ContentSHA256 != "" && cached.ContentSHA256 == file.ContentSHA256 {
				records = cached.Records
			} else {
				scanned, scannedSHA256, scanErr := scanHistoryFileWithContentSHA(outputDir, file.Path, nil)
				switch {
				case scannedSHA256 == "":
					index.Warnings = append(index.Warnings, historyScanFingerprintError(file.Path, scanErr).Error())
					if progress != nil {
						progress(i+1, total)
					}
					continue
				case scannedSHA256 != file.ContentSHA256:
					index.Warnings = append(index.Warnings, fmt.Sprintf("history transcript changed between fingerprint and scan: %s", file.Path))
					if progress != nil {
						progress(i+1, total)
					}
					continue
				case scanErr != nil:
					index.Warnings = append(index.Warnings, scanErr.Error())
					if progress != nil {
						progress(i+1, total)
					}
					continue
				}
				records = scanned
			}
		} else {
			// Cache-empty files take this path: parsing and SHA-256 consume the
			// transcript through one bounded stream.
			scanned, contentSHA256, scanErr := scanHistoryFileWithContentSHA(outputDir, file.Path, file.Info)
			if contentSHA256 == "" {
				index.Warnings = append(index.Warnings, historyScanFingerprintError(file.Path, scanErr).Error())
				if progress != nil {
					progress(i+1, total)
				}
				continue
			}
			file.ContentSHA256 = contentSHA256
			fingerprintedFiles = append(fingerprintedFiles, file.historySessionFile)
			if scanErr != nil {
				// A parse failure is still fingerprinted when the complete regular
				// file was read safely, matching the prior hash-then-scan behavior.
				index.Warnings = append(index.Warnings, scanErr.Error())
				if progress != nil {
					progress(i+1, total)
				}
				continue
			}
			records = scanned
		}
		// Only files that scanned cleanly (or were reused) are cached; a file
		// that errored is left out so the next refresh retries it. Branch is
		// build context, so v6 stores the raw records and annotates a copy below.
		newCache.Files[rel] = historyScanCacheEntry{
			ContentSHA256: file.ContentSHA256,
			Records:       records,
		}
		records = annotateHistoryRecordBranches(records, rel, branchByPath)

		for _, record := range records {
			if record.Kind == "decision" {
				dedupeKey := normalizeHistorySearchText(record.Summary)
				if _, ok := seenDecisions[dedupeKey]; ok {
					continue
				}
				seenDecisions[dedupeKey] = struct{}{}
			}
			index.Records = append(index.Records, record)
		}
		if progress != nil {
			progress(i+1, total)
		}
	}
	saveHistoryScanCache(outputDir, newCache)
	sort.Slice(index.Records, func(i, j int) bool {
		if index.Records[i].Kind != index.Records[j].Kind {
			return index.Records[i].Kind < index.Records[j].Kind
		}
		if index.Records[i].Path != index.Records[j].Path {
			return index.Records[i].Path < index.Records[j].Path
		}
		return index.Records[i].Line < index.Records[j].Line
	})
	transcriptsFingerprint := historyTranscriptFilesFingerprint(outputDir, fingerprintedFiles)
	source := &historySourceManifest{
		GeneratedAt:            now,
		IndexPath:              historyIndexPath,
		SessionsFingerprint:    brainSessionsFingerprint(outputDir),
		TranscriptsFingerprint: transcriptsFingerprint,
		Records:                len(index.Records),
		Warnings:               append([]string(nil), index.Warnings...),
	}
	for _, record := range index.Records {
		switch record.Kind {
		case "decision":
			source.Decisions++
		case "learning":
			source.Learnings++
		case "validation":
			source.Validations++
		case "tool_call":
			source.ToolCalls++
		case "code_fact":
			source.CodeFacts++
		}
	}
	return index, source, nil
}

func historyScanFingerprintError(path string, err error) error {
	if err != nil {
		return err
	}
	return fmt.Errorf("history transcript scan returned no content fingerprint: %s", path)
}

