240	func writeBrainHistoryIndexAndSourceLocked(outputDir string, now time.Time, progress historyIndexProgress) (*historySourceManifest, error) {
241		index, source, err := buildBrainHistoryIndex(outputDir, now, progress)
242		if err != nil {
243			return nil, err
244		}
245		data, err := json.MarshalIndent(index, "", "  ")
246		if err != nil {
247			return nil, err
248		}
249		data = append(data, '\n')
250		if err := writeBrainRelativeFileAtomic(outputDir, historyIndexPath, data, 0o600); err != nil {
251			return nil, fmt.Errorf("write history index: %w", err)
252		}
253		// Build the derived BM25 index alongside its truth so the search/query verbs
254		// do not pay a first-query rebuild. Best-effort: the query path rebuilds it
255		// lazily on any failure, so this must never fail the refresh.
256		if db, ftsErr := openHistoryFTSLocked(outputDir, index); ftsErr == nil {
257			_ = db.Close()
258		}
259		manifest, err := loadBrainManifest(outputDir)
260		if err != nil {
261			return nil, err
262		}
263		if manifest.Sources == nil {
264			manifest.Sources = &brainSources{}
265		}
266		manifest.Sources.History = source
267		if manifest.GeneratedAt.IsZero() {
268			manifest.GeneratedAt = now
269		}
270		if err := writeBrainManifestAndReadme(outputDir, *manifest); err != nil {
271			return nil, err
272		}
273		return source, nil
274	}
