276	func buildBrainHistoryIndex(outputDir string, now time.Time, progress historyIndexProgress) (historyIndex, *historySourceManifest, error) {
277		sessionsRoot := filepath.Join(outputDir, exportSessionsDirectory)
278		index := historyIndex{GeneratedAt: now}
279		if _, err := os.Stat(sessionsRoot); err != nil {
280			if os.IsNotExist(err) {
281				return index, nil, errors.New("session history missing; run `entire brain refresh sessions` first")
282			}
283			return index, nil, err
284		}
285		files, err := collectHistorySessionFiles(sessionsRoot, &index.Warnings)
286		if err != nil {
287			return index, nil, err
288		}
289	
290		prevCache := loadHistoryScanCache(outputDir)
291		newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
292		manifest, _ := loadBrainManifest(outputDir)
293		branchByPath := historyBranchByTranscriptPath(manifest)
294		sessionByPath := historySessionByTranscriptPath(manifest)
295		// Session tombstones (Phase 4): excluded sessions are understood BEFORE
296		// derived indexing — their transcripts are skipped entirely (no records,
297		// no exchanges, no cache entry), counted without retaining content.
298		excludedByPath := excludedTranscriptPaths(manifest, loadSessionTombstones(outputDir))
299		repoKey := ""
300		if manifest != nil {
301			repoKey = manifest.RepoKey
302		}
303	
304		total := len(files)
305		if progress != nil {
306			progress(0, total)
307		}
308		seenDecisions := map[string]struct{}{}
309		// Re-exported sessions (the same session written under multiple transcript
310		// paths) produce byte-identical exchanges with identical IDs — measured at
311		// 17–31% of exchange records on real brains. Files iterate newest-first, so
312		// keeping the first occurrence of each exchange ID retains the newest
313		// export's copy (which also carries any appended assistant output).
314		seenExchanges := map[string]struct{}{}
315		incompleteExchanges := 0
316		excludedSessions := map[string]struct{}{}
317		for i, file := range files {
318			rel, relErr := filepath.Rel(outputDir, file.Path)
319			if relErr != nil {
320				rel = file.Path
321			}
322			rel = filepath.ToSlash(rel)
323			if sessionID, excluded := excludedByPath[rel]; excluded {
324				excludedSessions[sessionID] = struct{}{}
325				if progress != nil {
326					progress(i+1, total)
327				}
328				continue
329			}
330	
331			var records []historyRecord
332			var incomplete int
333			if cached, ok := prevCache.Files[rel]; ok && cached.Size == file.Size && cached.ModUnixNano == file.ModUnixNano {
334				records = cached.Records
335				incomplete = cached.IncompleteExchanges
336			} else {
337				scanned, scanErr := scanHistoryFile(outputDir, file.Path)
338				if scanErr != nil {
339					index.Warnings = append(index.Warnings, scanErr.Error())
340					if progress != nil {
341						progress(i+1, total)
342					}
343					continue
344				}
345				records = scanned
346				// Conversation exchanges are an additive experimental projection; an
347				// extraction failure downgrades to classic records with a warning
348				// rather than dropping the whole file.
349				conversationScan, convErr := scanConversationTranscript(file.Path)
350				if convErr != nil {
351					index.Warnings = append(index.Warnings, fmt.Sprintf("conversation exchanges skipped for %s: %v", rel, convErr))
352				} else {
353					records = append(records, conversationExchangeRecords(rel, conversationScan)...)
354					incomplete = conversationScan.Incomplete
355				}
356			}
357			records = annotateHistoryRecordBranches(records, rel, branchByPath)
358			records = annotateConversationIdentity(records, rel, repoKey, sessionByPath)
359			incompleteExchanges += incomplete
360			// Only files that scanned cleanly (or were reused) are cached; a file
361			// that errored is left out so the next refresh retries it.
362			newCache.Files[rel] = historyScanCacheEntry{Size: file.Size, ModUnixNano: file.ModUnixNano, Records: records, IncompleteExchanges: incomplete}
363	
364			for _, record := range records {
365				if record.Kind == "decision" {
366					dedupeKey := normalizeHistorySearchText(record.Summary)
367					if _, ok := seenDecisions[dedupeKey]; ok {
368						continue
369					}
370					seenDecisions[dedupeKey] = struct{}{}
371				}
372				if record.Kind == conversationKind {
373					if _, ok := seenExchanges[record.ID]; ok {
374						continue
375					}
376					seenExchanges[record.ID] = struct{}{}
377				}
378				index.Records = append(index.Records, record)
379			}
380			if progress != nil {
381				progress(i+1, total)
382			}
383		}
384		saveHistoryScanCache(outputDir, newCache)
385		sort.Slice(index.Records, func(i, j int) bool {
386			if index.Records[i].Kind != index.Records[j].Kind {
387				return index.Records[i].Kind < index.Records[j].Kind
388			}
389			if index.Records[i].Path != index.Records[j].Path {
390				return index.Records[i].Path < index.Records[j].Path
391			}
392			return index.Records[i].Line < index.Records[j].Line
393		})
394		source := &historySourceManifest{
395			GeneratedAt:         now,
396			IndexPath:           historyIndexPath,
397			SessionsFingerprint: brainSessionsFingerprint(outputDir),
398			Records:             len(index.Records),
399			IncompleteExchanges: incompleteExchanges,
400			ExcludedSessions:    len(excludedSessions),
401			Warnings:            append([]string(nil), index.Warnings...),
402		}
403		for _, record := range index.Records {
404			switch record.Kind {
405			case "decision":
406				source.Decisions++
407			case "learning":
408				source.Learnings++
409			case "validation":
410				source.Validations++
411			case "tool_call":
412				source.ToolCalls++
413			case "code_fact":
414				source.CodeFacts++
415			case conversationKind:
416				source.Exchanges++
417			}
418		}
419		return index, source, nil
420	}
