422	// historySessionByTranscriptPath maps each exported transcript path to its
423	// session manifest entry so exchange records can carry session identity.
424	func historySessionByTranscriptPath(manifest *exportManifest) map[string]exportSession {
425		out := map[string]exportSession{}
426		if manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
427			return out
428		}
429		for _, session := range manifest.Sources.Sessions.Sessions {
430			rel := filepath.ToSlash(strings.TrimSpace(session.TranscriptPath))
431			if rel == "" {
432				continue
433			}
434			out[rel] = session
435		}
436		return out
437	}
