439	// annotateConversationIdentity fills the manifest-derived identity of exchange
440	// records: session id, agent, session time, and the stable conversation: ID.
441	// Like branch annotation it only fills empty fields, so records reused from the
442	// scan cache keep their first-computed identity.
443	func annotateConversationIdentity(records []historyRecord, rel, repoKey string, sessionByPath map[string]exportSession) []historyRecord {
444		needsAnnotation := false
445		for i := range records {
446			if records[i].Kind == conversationKind && records[i].ID == "" {
447				needsAnnotation = true
448				break
449			}
450		}
451		if !needsAnnotation {
452			return records
453		}
454		session, hasSession := sessionByPath[rel]
455		out := append([]historyRecord(nil), records...)
456		for i := range out {
457			if out[i].Kind != conversationKind || out[i].ID != "" {
458				continue
459			}
460			sessionID := ""
461			if hasSession {
462				sessionID = strings.TrimSpace(session.SessionID)
463				if out[i].Agent == "" {
464					out[i].Agent = session.Agent
465				}
466				if out[i].CreatedAt == "" && !session.CreatedAt.IsZero() {
467					out[i].CreatedAt = session.CreatedAt.UTC().Format(time.RFC3339)
468				}
469			}
470			out[i].SessionID = sessionID
471			id, degraded := conversationExchangeID(repoKey, sessionID, out[i].TurnOrdinal, out[i].RequestDigest, out[i].SourceDigest)
472			out[i].ID = id
473			out[i].IdentityDegraded = degraded
474		}
475		return out
476	}
