478	func historyBranchByTranscriptPath(manifest *exportManifest) map[string]string {
479		out := map[string]string{}
480		if manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
481			return out
482		}
483		defaultBranch := strings.TrimSpace(manifest.Sources.Sessions.DefaultBranch)
484		if defaultBranch == "" {
485			defaultBranch = strings.TrimSpace(manifest.DefaultBranch)
486		}
487		if defaultBranch == "" {
488			defaultBranch = distillDefaultBranch
489		}
490		for _, session := range manifest.Sources.Sessions.Sessions {
491			rel := filepath.ToSlash(strings.TrimSpace(session.TranscriptPath))
492			if rel == "" {
493				continue
494			}
495			branch := strings.TrimSpace(session.Branch)
496			if branch == "" {
497				branch = defaultBranch
498			}
499			out[rel] = branch
500		}
501		return out
502	}
