504	func annotateHistoryRecordBranches(records []historyRecord, rel string, branchByPath map[string]string) []historyRecord {
505		branch := historyRecordBranchForPath(rel, branchByPath)
506		if branch == "" {
507			return records
508		}
509		out := append([]historyRecord(nil), records...)
510		for i := range out {
511			if out[i].Branch == "" {
512				out[i].Branch = branch
513			}
514		}
515		return out
516	}
