518	func historyRecordBranchForPath(path string, branchByPath map[string]string) string {
519		rel := filepath.ToSlash(strings.TrimSpace(path))
520		if rel == "" {
521			return ""
522		}
523		if branch := strings.TrimSpace(branchByPath[rel]); branch != "" {
524			return branch
525		}
526		if strings.HasPrefix(rel, "sessions/branches/") {
527			rest := strings.TrimPrefix(rel, "sessions/branches/")
528			if idx := strings.Index(rest, "/"); idx > 0 {
529				return rest[:idx]
530			}
531		}
532		if strings.HasPrefix(rel, "sessions/") {
533			rest := strings.TrimPrefix(rel, "sessions/")
534			if idx := strings.Index(rest, "/"); idx > 0 {
535				return rest[:idx]
536			}
537		}
538		return ""
539	}
