541	// loadHistoryScanCache reads the per-file scan cache. It always returns a
542	// usable (non-nil map) value: any read/parse error or a version mismatch
543	// yields an empty cache so the index simply rebuilds from scratch.
544	// The cache stores every indexed record for every session, which at scale is
545	// hundreds of megabytes of JSON. It is gzip-compressed on disk to bound the
546	// footprint (the record text compresses heavily).
547	func loadHistoryScanCache(outputDir string) historyScanCache {
548		empty := historyScanCache{Version: historyScanCacheVersion, Files: map[string]historyScanCacheEntry{}}
549		data, err := os.ReadFile(filepath.Join(outputDir, filepath.FromSlash(historyScanCachePath)))
550		if err != nil {
551			return empty
552		}
553		gz, err := gzip.NewReader(bytes.NewReader(data))
554		if err != nil {
555			return empty
556		}
557		defer gz.Close()
558		// Bound the decompressed stream so a gzip bomb cannot exhaust memory; an
559		// over-cap or truncated stream simply rebuilds the cache from scratch.
560		limited := io.LimitReader(gz, semanticSnapshotMaxBytes())
561		var cache historyScanCache
562		if err := json.NewDecoder(limited).Decode(&cache); err != nil {
563			return empty
564		}
565		if cache.Version != historyScanCacheVersion || cache.Files == nil {
566			return empty
567		}
568		return cache
569	}
570	
571	// saveHistoryScanCache persists the per-file scan cache. Failures are
572	// non-fatal: a missing or unwritable cache only costs a full rebuild next time.
573	func saveHistoryScanCache(outputDir string, cache historyScanCache) {
574		var buf bytes.Buffer
575		gz := gzip.NewWriter(&buf)
576		if err := json.NewEncoder(gz).Encode(cache); err != nil {
577			return
578		}
579		if err := gz.Close(); err != nil {
580			return
581		}
582		_ = writeBrainRelativeFileAtomic(outputDir, historyScanCachePath, buf.Bytes(), 0o600)
583	}
