585	func brainSessionsFingerprint(outputDir string) string {
586		manifest, err := loadBrainManifest(outputDir)
587		if err != nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
588			return ""
589		}
590		return sessionSourceFingerprint(manifest.Sources.Sessions)
