  2	
  3	import (
  4		"database/sql"
  5		"fmt"
  6		"path/filepath"
  7		"sort"
  8		"strconv"
  9		"strings"
 10		"time"
 11	)
 12	
 13	// history_fts.go builds a derived FTS5 BM25 index over the history records and
 14	// ranks the history arm of the unified search/query verbs with it. It is a rebuildable artifact, a
 15	// sibling of history/index.json (the truth): deleting the .sqlite file forces a
 16	// clean rebuild on the next query, and any open/build/query failure falls back
 17	// to the substring scorer, so the index is an optimization, never load-bearing.
 18	//
 19	// BM25 replaces the hand-rolled coverage gate (historyRequiredQueryMatches),
 20	// whose flat term-counting could not tell a high-value term ("embedding") from a
 21	// filler one ("one"/"state"): every relaxation of the gate that admitted a real
 22	// single-strong-term paraphrase also admitted two-weak-term noise. BM25's IDF
 23	// down-weights common terms by corpus frequency, so an OR of the query terms
 24	// surfaces the doc that is strongly about the rare term while honest empties
 25	// (no term present at all) still return nothing.
 26	
 27	const (
 28		historyFTSFileName = "index-fts.sqlite"
 29		// historyFTSSchema v2: conversation exchange rows are indexed (their bounded
 30		// search projection lives in Summary) and excluded from general ranking
 31		// unless the exchange kind is explicitly selected.
 32		historyFTSSchema = "2"
 33	)
 34	
 35	// historyFTSRelevanceCutoff keeps only matches scoring at least this fraction of
 36	// the query's top match. BM25 score magnitude is not comparable across queries,
 37	// but within one query it is: an OR query matches every record sharing any term,
 38	// so a strong query grows a long tail of records that matched only one common or
 39	// stemmed term (e.g. "updates" hitting "Update File") far below the best hit.
 40	// Cutting relative to the top — not an absolute floor — trims that tail without a
 41	// corpus-specific constant. Tunable once a history eval lands.
 42	const historyFTSRelevanceCutoff = 0.30
 43	
 44	func historyFTSDBPath(brainDir string) string {
 45		return filepath.Join(brainDir, historyDirName, historyFTSFileName)
 46	}
 47	
 48	func historyFTSDBRelPath() string {
 49		return filepath.ToSlash(filepath.Join(historyDirName, historyFTSFileName))
 50	}
 51	
 52	// historyFTSContent is the searchable text for a record. It indexes two forms so
 53	// both spaced and camelCase queries hit the same identifier: the camel-split,
 54	// lowercased normalization (so "attribution base" matches "AttributionBaseCommit")
 55	// and the raw lowercase (so the single token "attributionbasecommit" matches too)
 56	// — the same dual normalized/raw strategy the substring matcher already uses.
 57	func historyFTSContent(r historyRecord) string {
 58		raw := r.Summary + " " + strings.Join(r.Terms, " ") + " " + r.Path
 59		return normalizeHistorySearchText(raw) + " " + strings.ToLower(raw)
 60	}
 61	
 62	// historyFTSMatchExpr turns a query into a safe FTS5 OR expression over its
 63	// stopword-filtered terms and identifiers. Each term is wrapped as an FTS5 string
 64	// literal (double-quoted, embedded quotes doubled) so query operators and
 65	// punctuation can never reach the FTS parser. Empty when the query reduces to no
 66	// usable term, which the caller treats as "fall back to the substring scorer".
 67	func historyFTSMatchExpr(query string) string {
 68		parts := make([]string, 0, 8)
 69		for _, t := range historyQueryAllTerms(query) {
 70			t = strings.ToLower(strings.TrimSpace(t))
 71			if t == "" {
 72				continue
 73			}
 74			parts = append(parts, `"`+strings.ReplaceAll(t, `"`, `""`)+`"`)
 75		}
 76		if len(parts) == 0 {
 77			return ""
 78		}
 79		return strings.Join(parts, " OR ")
 80	}
 81	
 82	func historyFTSFingerprint(index historyIndex) string {
 83		return index.GeneratedAt.UTC().Format(time.RFC3339Nano) + ":" + strconv.Itoa(len(index.Records))
 84	}
 85	
 86	// openHistoryFTS opens (and rebuilds if stale) the derived BM25 index. The index
 87	// is keyed by a fingerprint of the history index it was built from, so a refresh
 88	// that regenerates history/index.json triggers a clean rebuild here.
 89	//
 90	// Locking is double-checked: the fresh-index fast path opens WITHOUT the
 91	// exclusive brain lock — queries vastly outnumber rebuilds, and taking the
 92	// write lock on the read path would serialize every concurrent search and
 93	// time out (10s) against any long-running writer. Only a stale/missing index
 94	// takes the lock, re-checking freshness under it because another process may
 95	// have rebuilt while we waited. Concurrent readers of the fresh index are
 96	// safe: the store is WAL-mode SQLite with a busy timeout.
 97	func openHistoryFTS(brainDir string, index historyIndex) (*sql.DB, error) {
 98		if db, err := openHistoryFTSIfFresh(brainDir, index); err == nil && db != nil {
 99			return db, nil
100		}
101		var db *sql.DB
102		err := withBrainWriteLock(brainDir, func() error {
103			var runErr error
104			db, runErr = openHistoryFTSLocked(brainDir, index)
105			return runErr
106		})
107		return db, err
108	}
109	
110	// openHistoryFTSIfFresh returns an open handle when the on-disk index already
111	// matches the current history index, (nil, nil) when it is stale or missing.
112	func openHistoryFTSIfFresh(brainDir string, index historyIndex) (*sql.DB, error) {
113		path, err := prepareBrainRelativeSQLiteFile(brainDir, historyFTSDBRelPath())
114		if err != nil {
115			return nil, err
116		}
117		db, err := sql.Open(sqliteDriverName, path)
118		if err != nil {
119			return nil, err
120		}
121		db.SetMaxOpenConns(1)
122		for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA journal_mode=WAL;"} {
123			if _, err := db.Exec(pragma); err != nil {
124				db.Close()
125				return nil, err
126			}
127		}
128		if historyFTSFresh(db, index) {
129			return db, nil
130		}
131		db.Close()
132		return nil, nil
133	}
134	
135	func openHistoryFTSLocked(brainDir string, index historyIndex) (*sql.DB, error) {
136		path, err := prepareBrainRelativeSQLiteFile(brainDir, historyFTSDBRelPath())
137		if err != nil {
138			return nil, err
139		}
140		db, err := sql.Open(sqliteDriverName, path)
141		if err != nil {
142			return nil, err
143		}
144		// Pin a single connection so connection-scoped PRAGMAs (busy_timeout) below
145		// apply to every query/build, not just whichever pooled connection ran them.
146		db.SetMaxOpenConns(1)
147		for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA journal_mode=WAL;"} {
148			if _, err := db.Exec(pragma); err != nil {
149				db.Close()
150				return nil, err
151			}
152		}
153		if historyFTSFresh(db, index) {
154			return db, nil
155		}
156		if err := buildHistoryFTS(db, index); err != nil {
157			db.Close()
158			return nil, err
159		}
160		return db, nil
161	}
