163	// historyFTSFresh reports whether the existing index matches the current history
164	// index. Any error (missing tables, unreadable meta) is treated as stale so the
165	// caller rebuilds rather than failing.
166	func historyFTSFresh(db *sql.DB, index historyIndex) bool {
167		rows, err := db.Query(`SELECT key, value FROM history_fts_meta`)
168		if err != nil {
169			return false
170		}
171		defer rows.Close()
172		got := map[string]string{}
173		for rows.Next() {
174			var k, v string
175			if err := rows.Scan(&k, &v); err != nil {
176				return false
177			}
178			got[k] = v
179		}
180		if rows.Err() != nil {
181			return false // a driver error mid-iteration must read as stale, not fresh
182		}
183		return got["schema"] == historyFTSSchema && got["fingerprint"] == historyFTSFingerprint(index)
184	}
185	
186	func buildHistoryFTS(db *sql.DB, index historyIndex) error {
187		tx, err := db.Begin()
188		if err != nil {
189			return err
190		}
191		defer tx.Rollback()
192		for _, stmt := range []string{
193			`DROP TABLE IF EXISTS history_fts`,
194			`DROP TABLE IF EXISTS history_fts_meta`,
195			`CREATE TABLE history_fts_meta(key TEXT PRIMARY KEY, value TEXT)`,
196			`CREATE VIRTUAL TABLE history_fts USING fts5(content, kind UNINDEXED, rec_order UNINDEXED, tokenize='porter unicode61')`,
197		} {
198			if _, err := tx.Exec(stmt); err != nil {
199				return fmt.Errorf("history fts schema: %w", err)
200			}
201		}
202		ins, err := tx.Prepare(`INSERT INTO history_fts(content, kind, rec_order) VALUES (?, ?, ?)`)
203		if err != nil {
204			return err
205		}
206		defer ins.Close()
207		for i, r := range index.Records {
