220	// rankHistoryViaFTS ranks records with the BM25 index, returning ok=false on any
221	// failure (or a degenerate query) so the caller falls back to the substring
222	// scorer. It dedups by normalized summary like the scorer does. NOTE on the sign:
223	// SQLite FTS5 bm25() is the BM25 score *negated* (per the FTS5 docs), so a better
224	// match is MORE NEGATIVE and `ORDER BY bm25()` ASC returns best-first. We negate it
225	// back to a positive display score (higher = better) for the cutoff and Score.
226	func rankHistoryViaFTS(brainDir string, index historyIndex, kind, query string, limit int) ([]scoredHistoryRecord, bool) {
227		return rankHistoryViaFTSCutoff(brainDir, index, kind, query, limit, historyFTSRelevanceCutoff)
228	}
229	
230	// rankHistoryViaFTSCutoff is rankHistoryViaFTS with the relevance cutoff as a
231	// parameter, so the history eval can sweep it (the shipped 0.30 was chosen by
232	// inspection, "tunable once a history eval lands"). Production callers go
233	// through rankHistoryViaFTS and always get the shipped constant.
234	func rankHistoryViaFTSCutoff(brainDir string, index historyIndex, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool) {
235		if limit <= 0 {
236			return nil, false
237		}
238		expr := historyFTSMatchExpr(query)
239		if expr == "" {
240			return nil, false
241		}
242		db, err := openHistoryFTS(brainDir, index)
243		if err != nil {
244			return nil, false
245		}
246		defer db.Close()
247	
248		args := []any{expr}
249		var sb strings.Builder
250		sb.WriteString(`SELECT CAST(rec_order AS INTEGER), bm25(history_fts) FROM history_fts WHERE history_fts MATCH ?`)
251		if allowed := historyInspectKinds(kind); len(allowed) > 0 {
252			kinds := make([]string, 0, len(allowed))
253			for k := range allowed {
254				kinds = append(kinds, k)
255			}
256			sort.Strings(kinds)
257			placeholders := make([]string, len(kinds))
258			for i, k := range kinds {
259				placeholders[i] = "?"
260				args = append(args, k)
261			}
262			sb.WriteString(" AND kind IN (" + strings.Join(placeholders, ",") + ")")
263		} else {
264			// User-prompt records add noise to general ranking (measured: they displace
265			// relevant content without improving recall); conversation exchanges are
266			// opt-in via the explicit conversation source. Surface them only via their
267			// explicit kinds, never the broad history/sessions sweep.
268			sb.WriteString(" AND kind NOT IN ('request', '" + conversationKind + "')")
269		}
270		sb.WriteString(" ORDER BY bm25(history_fts) LIMIT ?")
271		args = append(args, limit*4) // over-fetch so summary dedup still fills limit
272	
273		rows, err := db.Query(sb.String(), args...)
274		if err != nil {
275			return nil, false
276		}
277		defer rows.Close()
278		out := make([]scoredHistoryRecord, 0, limit)
279		seen := map[string]struct{}{}
280		var topScore float64
281		for rows.Next() {
282			var order int
283			var bm float64
284			if err := rows.Scan(&order, &bm); err != nil {
285				return nil, false
286			}
287			if order < 0 || order >= len(index.Records) {
288				continue
289			}
290			// Rows arrive best-first (bm25 ascending), so the first kept row is the
291			// top score and the cutoff can stop the scan: every later row is weaker.
292			score := -bm // bm is SQLite's negated BM25 (<= 0); -bm is positive, higher = better
293			if topScore == 0 {
294				topScore = score
295			} else if score < cutoff*topScore {
296				break
297			}
298			rec := index.Records[order]
299			key := normalizeHistorySearchText(rec.Summary)
300			if _, ok := seen[key]; ok {
301				continue
302			}
303			seen[key] = struct{}{}
304			out = append(out, scoredHistoryRecord{Record: rec, Score: int(score*1000 + 0.5), Order: order})
305			if len(out) >= limit {
306				break
307			}
308		}
309		if rows.Err() != nil {
310			return nil, false
311		}
312		return out, true
313	}

