	for _, entry := range cache.Files {
		if entry.IncompleteExchanges != 1 {
			t.Fatalf("cached incomplete = %d, want 1", entry.IncompleteExchanges)
		}
		exchanges := 0
		for _, record := range entry.Records {
			if record.Kind == conversationKind {
