		if topScore == 0 {
			topScore = score
		} else if score < cutoff*topScore {
			break
		}
		key := normalizeHistorySearchText(rec.Summary)
		if _, duplicate := seen[key]; duplicate {
			continue
		}
		seen[key] = struct{}{}
