const (
	brainBriefGitIntentTermLimit   = 6
	brainBriefGitIntentCommitLimit = 16
	brainBriefGitIntentPathLimit   = 64
	brainBriefGitIntentOutputLimit = 64 * 1024
	brainBriefGitIntentTimeout     = 100 * time.Millisecond
