// brainBriefPromoteGitIntentFile closes a narrow operational-code blind spot.
// Semantic providers often expose only a file record for shell/config files (or
// do not parse them at all), while retained sessions need not put their paths in
// the top history window. A strongly matching commit subject is useful local
// provenance for those files, but only after the normal brief has failed to
// produce either a concrete action or a strong operational path candidate.
//
// The overlay is deliberately read-only and fail-closed: it searches current
// ancestry only, accepts one current regular operational/config file, and never
// treats task text as a revision, pathspec, or regular expression.
func brainBriefPromoteGitIntentFile(
	ctx context.Context,
	runner CommandRunner,
	repoRoot, task string,
	report *brainBriefReport,
) bool {
	if report == nil || runner == nil || len(report.ActionChecklist) != 0 {
		return false
	}
	terms := brainBriefGitIntentTerms(task)
	if len(terms) < 2 || !brainBriefGitIntentOperationalTask(task, terms) ||
		brainBriefGitIntentHasStrongCandidate(*report, terms) {
		return false
	}
	path, ok := brainBriefGitIntentFile(ctx, runner, repoRoot, task, terms)
	if !ok || path == "" {
		return false
	}
	report.LikelyEditFiles = brainBriefGitIntentMergeEdit(path, report.LikelyEditFiles)
	report.LikelyFiles = brainBriefMergeLikelyFiles(report.LikelyEditFiles, report.LikelyTestFiles)
	return true
}

func brainBriefGitIntentTerms(task string) []string {
	terms := brainBriefPostIndexLocatorTerms(task)
	if len(terms) > brainBriefGitIntentTermLimit {
		terms = terms[:brainBriefGitIntentTermLimit]
	}
	out := make([]string, 0, len(terms))
	for _, term := range terms {
		if brainBriefLiteralLocatorTerm(term) && len(term) <= 40 {
			out = append(out, term)
		}
	}
	return out
}

func brainBriefGitIntentOperationalTask(task string, terms []string) bool {
	for _, term := range terms {
		switch {
		case strings.HasPrefix(term, "install"), strings.HasPrefix(term, "config"),
			strings.HasPrefix(term, "workflow"), strings.HasPrefix(term, "compiler"),
			strings.HasPrefix(term, "build"), strings.HasPrefix(term, "packag"),
			strings.HasPrefix(term, "releas"), strings.HasPrefix(term, "hook"),
			strings.HasPrefix(term, "manifest"), strings.HasPrefix(term, "toolchain"),
			strings.HasPrefix(term, "deprecat"), strings.HasPrefix(term, "environment"),
			term == "cgo", term == "flags", term == "lane", term == "macos", term == "darwin":
			return true
		}
	}
	// The shared locator intentionally ignores two-character tokens. Keep the
	// common standalone CI intent without relaxing the safe Git term boundary.
	for _, word := range strings.FieldsFunc(strings.ToLower(task), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsNumber(r)
	}) {
		if word == "ci" {
			return true
		}
	}
	return false
}

func brainBriefGitIntentHasStrongCandidate(report brainBriefReport, terms []string) bool {
	for i, path := range report.LikelyEditFiles {
		clean, ok := cleanBrainBriefLikelyFile(path)
		if !ok {
			clean, ok = brainBriefGitIntentCleanOperationalPath(path)
		}
		if !ok {
			continue
		}
		hits, domainHits := brainBriefGitIntentTextHits(clean, terms)
		if (i == 0 && hits >= 2 && domainHits >= 2) ||
			(hits >= 3 && domainHits >= 2) {
			return true
		}
	}
	return false
}

func brainBriefGitIntentFile(
	ctx context.Context,
	runner CommandRunner,
	repoRoot, task string,
	terms []string,
) (string, bool) {
	if strings.TrimSpace(repoRoot) == "" || len(terms) < 2 || len(terms) > brainBriefGitIntentTermLimit {
		return "", false
	}
	for _, term := range terms {
		if !brainBriefLiteralLocatorTerm(term) || len(term) > 40 {
			return "", false
		}
	}
	streamer, ok := runner.(CommandStreamer)
	if !ok {
		return "", false
	}

	boundedCtx, cancel := context.WithTimeout(ctx, brainBriefGitIntentTimeout)
	defer cancel()
	logArgs := []string{
		"-c", "core.quotepath=false", "log", "--no-merges",
		"--max-count=" + strconv.Itoa(brainBriefGitIntentCommitLimit), "--regexp-ignore-case", "--fixed-strings",
		"--format=%H%x00%s", "-z",
	}
	grepCount := 0
	for _, term := range terms {
		// Generic work words such as "test" can fill the sixteen-commit
		// window before the domain-specific historical fix is reached. They
		// still contribute to final subject scoring, but only domain terms
		// select the bounded candidate window.
		if brainBriefGitIntentGenericTerm(term) {
			continue
		}
		// The value is letters/numbers only and --fixed-strings is set before
		// every pattern. Prefixing it inside --grep= prevents option, revision,
		// pathspec, and regex interpretation of task-controlled text.
		logArgs = append(logArgs, "--grep="+term)
		grepCount++
	}
	if grepCount == 0 {
		return "", false
	}
	logArgs = append(logArgs, "HEAD", "--")
	logOutput, ok := brainBriefGitIntentRead(boundedCtx, cancel, streamer, repoRoot, logArgs, brainBriefGitIntentOutputLimit)
	if !ok {
		return "", false
	}
	commits, ok := brainBriefGitIntentParseCommits(logOutput, terms)
	if !ok {
		return "", false
	}
	commit, ok := brainBriefGitIntentBestCommit(commits)
	if !ok {
		return "", false
	}

	remaining := brainBriefGitIntentOutputLimit - len(logOutput)
	if remaining <= 0 {
		return "", false
			if e != nil {
				rr = newSemanticRerankerForBranch(e, brainDir, branch)
			}
			factResults = factsToUnified(rankFactsFused(active, query, factLimit, false, rr))
			if rr != nil {
				rr.retain(all) // keep every present fact's vector; prune only departed facts (matches recall/brief)
				_ = rr.flush()
			}
		}
		if proposalsErr == nil {
			factResults = guardUnifiedFactResults(repoDir, all, proposals, factResults, candidateLimit)
		} else {
			factResults = guardUnifiedFactResults(repoDir, all, nil, factResults, candidateLimit)
			factResults = annotateProposalStateUnavailable(factResults)
		}
		if len(factResults) > 0 {
			lists = append(lists, factResults)
		}
	}

	// History — BM25 (lexical / hybrid), plus the gated semantic arm (hybrid /
	// vector; see history_vec.go). The FTS index is an optimization, never
	// load-bearing (see history_fts.go): on a build/open/query failure fall
	// back to the in-memory substring scorer. But a corrupt manifest, or a history
	// index the manifest declares yet is missing/unreadable, is a real storage
	// problem — surface it rather than returning silently-incomplete results. A
	// brain with no history source (nil) is legitimately skipped.
	historySem := historySemanticEmbedder(e)
	if includeHistory && (mode != modeVector || historySem != nil) {
		manifest, err := loadBrainManifest(brainDir)
		if err != nil {
			return nil, err
		}
		if manifest.Sources != nil && manifest.Sources.History != nil {
			source := manifest.Sources.History
			var lexicalHistoryIDs map[string]struct{}
			if mode != modeVector && historySem == nil {
				// The common BM25-only path hydrates its small result window from
				// the fresh FTS payload table. Legacy/stale/corrupt caches fall back
				// through the verified full JSON index and substring scorer.
				scored, _, _, rankErr := rankHistoryLexicalFromSource(brainDir, source, "history", query, limit*2)
				if rankErr != nil {
					return nil, fmt.Errorf("load history index: %w", rankErr)
				}
				if len(scored) > 0 {
					lists = append(lists, historyToUnified(scored))
				}
			} else {
				// Semantic history fusion and vector retrieval intentionally retain
				// the complete index: semantic scores map arbitrary record IDs back
				// to their payloads, not just the lexical top-k window.
				index, loadErr := loadBrainHistoryIndex(brainDir, source)
				if loadErr != nil {
					return nil, fmt.Errorf("load history index: %w", loadErr)
				}
				if mode != modeVector {
					scored, ok := rankHistoryViaFTS(brainDir, index, "history", query, limit*2)
					if !ok {
						scored = rankHistoryRecordsScored(index, "history", query, limit*2, 0)
					}
					if len(scored) > 0 {
						lexicalHistoryIDs = make(map[string]struct{}, len(scored))
						for _, record := range scored {
							lexicalHistoryIDs[record.Record.ID] = struct{}{}
						}
						lists = append(lists, historyToUnified(scored))
					}
				}
				if mode != modeLexical && historySem != nil {
					// Independently ranked history lists: global RRF fuses BM25 and
					// cosine, then gives calibrated term-disjoint evidence a second
					// vote without triple-counting lexical hits.
					scores := historySemanticScores(brainDir, historySem, query, candidateLimit, mode == modeHybrid)
					var sem historyVectorRanks
					if mode == modeVector {
						sem.ranked = rankHistorySemantic(index, scores, candidateLimit)
					} else {
						sem = rankHistorySemanticHybridRanks(index, scores, candidateLimit, lexicalHistoryIDs)
					}
					if len(sem.ranked) > 0 {
						lists = append(lists, historyToUnified(sem.ranked))
					}
					if len(sem.calibratedSemanticOnly) > 0 {
						lists = append(lists, historyToUnified(sem.calibratedSemanticOnly))
					}
				}
			}
		}
	}

	// Docs — lexical (search/query) and/or vector (vsearch/query). In hybrid mode
	// docs join BOTH arms, mirroring facts. A never-built doc index is skipped; a
	// corrupt/unreadable one is a real storage problem and is surfaced.
	var docIdx docIndex
	var derr error
	if includeDocs {
		docIdx, derr = loadDocIndex(brainDir)
	} else {
		derr = os.ErrNotExist
	}
	switch {
	case derr == nil && len(docIdx.Records) > 0:
		var lexicalDocIDs map[string]struct{}
		if mode != modeVector {
			// FTS is an optimization, never load-bearing: fall back to the in-memory
			// lexical scorer so docs don't vanish when the doc FTS index can't open.
			scored, ok := rankDocsViaFTS(brainDir, docIdx, query, candidateLimit)
			if !ok {
				scored = rankDocsLexical(docIdx, query, candidateLimit)
			}
			if len(scored) > 0 {
				lexicalDocIDs = make(map[string]struct{}, len(scored))
				for _, record := range scored {
					lexicalDocIDs[record.Record.ID] = struct{}{}
				}
				lists = append(lists, docsToUnified(scored))
			}
		}
		if mode != modeLexical && e != nil {
			vectorRanks := docsVectorRanked(
				brainDir, docIdx, query, e, candidateLimit, mode == modeHybrid, lexicalDocIDs,
			)
			if len(vectorRanks.ranked) > 0 {
				lists = append(lists, vectorRanks.ranked)
			}
			if len(vectorRanks.calibratedSemanticOnly) > 0 {
				lists = append(lists, vectorRanks.calibratedSemanticOnly)
			}
		}
	case derr != nil && !os.IsNotExist(derr):
		return nil, fmt.Errorf("load doc index: %w", derr)
	}

	return rrfMergeUnified(lists, limit), nil
}

func filterHistoryRetrievalSelfEchoes(scored []scoredHistoryRecord, query string) []scoredHistoryRecord {
	needle := strings.ToLower(strings.TrimSpace(query))
	if needle == "" {
		return scored
	}
	out := scored[:0]
	for _, item := range scored {
		kind := strings.ToLower(strings.TrimSpace(item.Record.Kind))
		summary := strings.ToLower(item.Record.Summary)
		brainInvocation := strings.Contains(summary, "entire brain search") ||
			strings.Contains(summary, "entire brain query") ||
			strings.Contains(summary, "entire brain brief") ||
			strings.Contains(summary, "brain_search") ||
			strings.Contains(summary, "brain_query") ||
			strings.Contains(summary, "brain_brief")
		if kind == "tool_call" && brainInvocation && strings.Contains(summary, needle) {
			continue
		}
		out = append(out, item)
	}
	return out
}

