	}
	var out []historyRecord
	var out []historyRecord
	for _, record := range index.Records {
		if record.Kind == conversationKind {
			out = append(out, record)
		}
	}
	return out
}

func TestHistoryIndexBuildsExchangeRecords(t *testing.T) {
