from __future__ import annotations
import hashlib
import pathlib
import subprocess

repo = pathlib.Path.cwd()
tracked = [pathlib.Path(p) for p in subprocess.check_output(["git", "ls-files"], text=True).splitlines()]
changed = [pathlib.Path(p) for p in subprocess.check_output(["git", "diff", "--name-only"], text=True).splitlines()]

def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def head_bytes(path: pathlib.Path) -> bytes:
    return subprocess.check_output(["git", "show", f"HEAD:{path.as_posix()}"])

pending: dict[bytes, bytes] = {}
for path in changed:
    if not (repo / path).is_file():
        continue
    old = digest(head_bytes(path)).encode()
    new = digest((repo / path).read_bytes()).encode()
    if old != new:
        pending[old] = new

for round_no in range(1, 12):
    if not pending:
        break
    before = {path: digest((repo / path).read_bytes()) for path in tracked if (repo / path).is_file()}
    touched: list[pathlib.Path] = []
    for path in tracked:
        full = repo / path
        if not full.is_file():
            continue
        data = full.read_bytes()
        updated = data
        for old, new in pending.items():
            updated = updated.replace(old, new)
        if updated != data:
            full.write_bytes(updated)
            touched.append(path)
    next_pending: dict[bytes, bytes] = {}
    for path in touched:
        after = digest((repo / path).read_bytes())
        prior = before[path]
        if prior != after:
            next_pending[prior.encode()] = after.encode()
    print(f"hash-repair round {round_no}: {len(touched)} reference files updated")
    pending = next_pending
else:
    raise SystemExit("hash repair did not converge")
